import React from 'react';
import { formatMoney } from 'utils/commonFunc';
import SummaryCard, { Figure, Operator, Row, Progress } from './SummaryCard';

const toNumber = value => Number(value || 0);
const GREEN = '#2e7d32';
const RED = '#c62828';
const BLUE = '#1565c0';

// The school-fee picture of one student: Total fee - Concession = Amount to pay on the first line, then how much was paid
// (refunds taken off) and what is still left, with a bar for how much of the fee is paid. Built from the same fee
// structure and payments the tables below list.
const FeeSummaryCard = ({ feeStructure = [], payments = [], refunds = [] }) => {
  const totalFee = feeStructure.reduce((sum, item) => sum + toNumber(item.actualAmount), 0);
  const concession = feeStructure.reduce((sum, item) => sum + toNumber(item.discountAmount), 0);
  const amountToPay = feeStructure.reduce(
    (sum, item) => sum + toNumber(item.expectedAmount || toNumber(item.actualAmount) - toNumber(item.discountAmount)),
    0
  );
  const paid = payments.reduce((sum, item) => sum + toNumber(item.amount), 0);
  const refunded = refunds.reduce((sum, item) => sum + toNumber(item.refundAmount), 0);
  const netPaid = paid - refunded;
  const balance = amountToPay - netPaid;
  const settled = balance <= 0;
  const status = settled
    ? { label: balance < 0 ? 'Paid extra' : 'Fully paid', color: GREEN }
    : { label: netPaid > 0 ? 'Part paid' : 'Not paid', color: netPaid > 0 ? '#ef6c00' : RED };

  return (
    <SummaryCard title="Fee Summary" status={status}>
      <Row>
        <Figure label="Total fee" value={formatMoney(totalFee)} />
        <Operator symbol="−" />
        <Figure label="Concession" value={formatMoney(concession)} tone="good" />
        <Operator symbol="=" />
        <Figure label="Amount to pay" value={formatMoney(amountToPay)} />
      </Row>
      <Row>
        <Figure
          label="Amount paid"
          value={formatMoney(netPaid)}
          tone="info"
          note={refunded ? `${formatMoney(paid)} paid, ${formatMoney(refunded)} refunded` : undefined}
        />
        <Figure
          label={balance < 0 ? 'Paid extra' : 'Balance to pay'}
          value={formatMoney(Math.abs(balance))}
          tone={settled ? 'good' : 'bad'}
        />
      </Row>
      <Progress value={netPaid} max={amountToPay} label="Fee paid" color={settled ? GREEN : BLUE} />
    </SummaryCard>
  );
};

export default FeeSummaryCard;
