import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Paper } from '@material-ui/core';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import SearchIcon from '@material-ui/icons/Search';
import ThumbUpAltIcon from '@material-ui/icons/ThumbUpAlt';
import ChatBubbleIcon from '@material-ui/icons/ChatBubble';
import FlagIcon from '@material-ui/icons/Flag';
import moment from 'moment';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import CustomInput from 'views/admin/Common/CustomInput';
import colors from 'config/colors';
import { courseStatic, employeeStatic, formStudentName } from 'config/constants';
import {
  formCourseSelectList,
  formResMessage,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
} from 'utils/commonFunc';
import { fetchBatchCourseService } from 'actions/admin/courses';
import { fetchSchoolCourseStudentsService } from 'actions/admin/students';
import { fetchStudentFeedbackService, sendStudentFeedbackService } from 'actions/admin/feedback';
import { showToast } from 'actions/admin/auth';
import { useFillHeight } from 'utils/useFillHeight';
import { useContainWheel } from 'utils/useContainWheel';
import { SkeletonRows } from 'views/admin/Common/Loader';

const MAX_CHARS = 500;

const KINDS = {
  POSITIVE: {
    label: 'Positive',
    hint: 'Praise, progress, good behaviour',
    color: '#2e7d32',
    icon: ThumbUpAltIcon,
    phrases: ['Good progress this week.', 'Very active and helpful in class.', 'Excellent performance in the test.'],
  },
  NEUTRAL: {
    label: 'Neutral',
    hint: 'A note or a request',
    color: '#1565c0',
    icon: ChatBubbleIcon,
    phrases: ['Please meet the class teacher.', 'Please sign the home work diary.', 'Please send the pending forms.'],
  },
  NEGATIVE: {
    label: 'Needs attention',
    hint: 'A concern to work on',
    color: '#e65100',
    icon: FlagIcon,
    phrases: [
      'Often late to school. Please check.',
      'Home work is not done regularly.',
      'Needs to pay more attention in class.',
    ],
  },
};
const KIND_KEYS = Object.keys(KINDS);

const Avatar = ({ name, size = 36, active }) => (
  <div
    style={{
      width: size,
      height: size,
      borderRadius: '50%',
      flexShrink: 0,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontWeight: 'bold',
      fontSize: size * 0.4,
      background: active ? colors.accent : `${colors.accent}1a`,
      color: active ? '#fff' : colors.accent,
    }}>
    {(name || '?').trim().charAt(0).toUpperCase()}
  </div>
);

// One earlier note: a coloured bar and round icon for its kind, the note itself as the main text, the kind as a small chip in the
// top right corner, then who wrote it and when, and whether the guardian has read it.
export const HistoryItem = ({ item }) => {
  const kind = KINDS[item.kind] || KINDS.NEUTRAL;
  const Icon = kind.icon;
  const by = [item.fromUserName, item.fromUserRole === 'ROLE_TEACHER' ? employeeStatic : 'Admin']
    .filter(Boolean)
    .join(' · ');
  return (
    <div
      style={{
        display: 'flex',
        gap: 12,
        padding: '12px 14px',
        marginBottom: 10,
        borderRadius: 10,
        background: '#fff',
        border: '1px solid #ece6f2',
        borderLeft: `4px solid ${kind.color}`,
      }}>
      <div
        style={{
          width: 34,
          height: 34,
          borderRadius: '50%',
          flexShrink: 0,
          background: `${kind.color}1a`,
          color: kind.color,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}>
        <Icon style={{ fontSize: 18 }} />
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 10 }}>
          <div style={{ fontSize: 14, whiteSpace: 'pre-wrap', wordBreak: 'break-word', minWidth: 0 }}>
            {item.message}
          </div>
          <span
            style={{
              flexShrink: 0,
              padding: '2px 10px',
              borderRadius: 12,
              background: `${kind.color}1a`,
              color: kind.color,
              fontSize: 11,
              fontWeight: 'bold',
              letterSpacing: 0.4,
              textTransform: 'uppercase',
              whiteSpace: 'nowrap',
            }}>
            {kind.label}
          </span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap', marginTop: 4 }}>
          <small className="text-muted">
            {by ? `By ${by} · ` : ''}
            {moment(item.creationDateTime).format('DD MMM YYYY, hh:mm A')}
          </small>
          <small style={{ color: item.seenDateTime ? '#2e7d32' : '#8b95a1', fontWeight: 600 }}>
            <i className={`fas fa-${item.seenDateTime ? 'check-double' : 'check'} mr-1`} />
            {item.seenDateTime ? `Seen · ${moment(item.seenDateTime).format('DD MMM, hh:mm A')}` : 'Not seen yet'}
          </small>
        </div>
      </div>
    </div>
  );
};

// Parent notes: a note about a student, sent straight to that student's guardian (a notification, never a public place). Any
// teacher (or the admin) can add a note about a student, so one student can have notes from several teachers - every note
// shows who wrote it and when, and whether the guardian has read it ("Seen" is recorded when the guardian opens the note in
// the app's Parent notes list or its notification). On the left the class and its students; on the right the chosen student:
// a new note (positive, neutral or needs attention) and, below it, everything already sent about them.
const StudentFeedbackPage = () => {
  const dispatch = useDispatch();
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);
  const courseList = useSelector(state => state.courses.batchCourseList) || [];
  const courseStudentList = useSelector(state => state.schools.courseStudentList) || [];
  const [courseId, setCourseId] = useState(0);
  const [studentId, setStudentId] = useState(0);
  const [search, setSearch] = useState('');
  const [kind, setKind] = useState('POSITIVE');
  const [message, setMessage] = useState('');
  const [history, setHistory] = useState([]);
  const [historyFilter, setHistoryFilter] = useState('ALL');
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [isLoadingStudents, setIsLoadingStudents] = useState(true);
  const [isSending, setIsSending] = useState(false);
  const [isFormOpen, setIsFormOpen] = useState(false);
  // Opened from a student's own page (?studentId=&courseId=&add=1): that class and student are chosen and the form is ready.
  const pending = useRef(
    (() => {
      const query = new URLSearchParams(window.location.search);
      return {
        courseId: Number(query.get('courseId')) || 0,
        studentId: Number(query.get('studentId')) || 0,
        add: query.get('add') === '1',
      };
    })()
  );
  const rootRef = useRef(null);
  const paneHeight = useFillHeight(rootRef);
  const listRef = useRef(null);
  const historyRef = useRef(null);
  useContainWheel(historyRef);
  useContainWheel(listRef);

  const courseOptions = useMemo(() => formCourseSelectList(courseList), [courseList]);
  const students = useMemo(() => {
    const q = search.trim().toLowerCase();
    return courseStudentList.filter(s => !q || formStudentName(s).toLowerCase().includes(q));
  }, [courseStudentList, search]);
  const student = courseStudentList.find(s => s.studentId === studentId);
  const kindInfo = KINDS[kind];

  useEffect(() => {
    const school = getGlobalSchoolUtils();
    const batch = getGlobalCurrentBatchUtils();
    dispatch(
      fetchBatchCourseService({
        token: loggedUserToken,
        schoolId: school?.schoolId,
        batchId: batch?.batchId,
        status: 'ACTIVE',
      })
    );
  }, []);

  useEffect(() => {
    if (!courseId && courseList.length) {
      const wanted = pending.current.courseId;
      setCourseId(courseList.some(item => item.courseId === wanted) ? wanted : courseList[0].courseId);
    }
  }, [courseList]);

  useEffect(() => {
    if (!courseId) return;
    const batch = getGlobalCurrentBatchUtils();
    setStudentId(0);
    setSearch('');
    // The class's first student is chosen once they load, so the page opens on someone's feedback and not on an empty prompt.
    let cancelled = false;
    setIsLoadingStudents(true);
    dispatch(fetchSchoolCourseStudentsService({ token: loggedUserToken, batchId: batch?.batchId, courseId }))
      .then(list => {
        if (!cancelled && Array.isArray(list) && list.length) {
          const wanted = pending.current.studentId;
          setStudentId(list.some(item => item.studentId === wanted) ? wanted : list[0].studentId);
        }
      })
      .finally(() => !cancelled && setIsLoadingStudents(false));
    return () => {
      cancelled = true;
    };
  }, [courseId]);

  const loadHistory = async id => {
    const school = getGlobalSchoolUtils();
    setIsLoadingHistory(true);
    try {
      setHistory(
        await fetchStudentFeedbackService({ token: loggedUserToken, schoolId: school?.schoolId, studentId: id })
      );
    } catch (err) {
      setHistory([]);
      dispatch(showToast(formResMessage(err), 'error'));
    }
    setIsLoadingHistory(false);
  };

  useEffect(() => {
    setHistoryFilter('ALL');
    setMessage('');
    setIsFormOpen(false);
    if (studentId && pending.current.add && studentId === pending.current.studentId) {
      setIsFormOpen(true);
    }
    if (studentId) pending.current = { courseId: 0, studentId: 0, add: false };
    if (studentId) loadHistory(studentId);
    else setHistory([]);
  }, [studentId]);

  const send = async () => {
    const school = getGlobalSchoolUtils();
    setIsSending(true);
    try {
      await sendStudentFeedbackService({
        token: loggedUserToken,
        schoolId: school?.schoolId,
        studentId,
        type: kind,
        message: message.trim(),
      });
      setMessage('');
      setIsFormOpen(false);
      dispatch(showToast(`Feedback sent to the guardian of ${formStudentName(student)}`, 'success'));
      loadHistory(studentId);
    } catch (err) {
      dispatch(showToast(formResMessage(err), 'error'));
    }
    setIsSending(false);
  };

  const counts = history.reduce((acc, item) => ({ ...acc, [item.kind]: (acc[item.kind] || 0) + 1 }), {});
  const shownHistory = historyFilter === 'ALL' ? history : history.filter(item => item.kind === historyFilter);

  return (
    <div className="content">
      <div
        ref={rootRef}
        style={{ display: 'flex', gap: 16, alignItems: 'stretch', height: paneHeight || undefined, minHeight: 360 }}>
        {/* the class and its students */}
        <Paper
          elevation={3}
          style={{
            flex: '0 0 340px',
            display: 'flex',
            flexDirection: 'column',
            borderRadius: 12,
            padding: 16,
            minHeight: 0,
          }}>
          <CustomSelect
            name="courseId"
            label={courseStatic}
            value={courseId}
            onChange={(name, value) => setCourseId(value)}
            options={courseOptions}
            applyLabelStyle={true}
          />
          <div style={{ position: 'relative', margin: '4px 0 8px' }}>
            <SearchIcon style={{ position: 'absolute', left: 8, top: 7, fontSize: 20, color: colors.grey3 }} />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search student"
              aria-label="Search student"
              style={{
                width: '100%',
                padding: '6px 10px 6px 34px',
                border: '1px solid #e2d9ea',
                borderRadius: 18,
                fontSize: 13,
                outline: 'none',
              }}
            />
          </div>
          <div ref={listRef} style={{ flex: 1, minHeight: 0, overflowY: 'auto', overscrollBehavior: 'contain' }}>
            {students.map(item => {
              const active = item.studentId === studentId;
              return (
                <div
                  key={item.studentId}
                  role="button"
                  tabIndex={0}
                  onClick={() => setStudentId(item.studentId)}
                  onKeyDown={e => e.key === 'Enter' && setStudentId(item.studentId)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    padding: '8px 10px',
                    borderRadius: 8,
                    cursor: 'pointer',
                    background: active ? colors.sidebarActiveItemBg : 'transparent',
                    borderLeft: `3px solid ${active ? colors.accent : 'transparent'}`,
                  }}>
                  <Avatar name={item.firstName} active={active} />
                  <div style={{ minWidth: 0 }}>
                    <div
                      style={{
                        fontSize: 14,
                        fontWeight: active ? 'bold' : 600,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}>
                      {formStudentName(item)}
                    </div>
                    <small className="text-muted">{item.registerNumber}</small>
                  </div>
                </div>
              );
            })}
            {isLoadingStudents && !students.length && <SkeletonRows rows={5} />}
            {!isLoadingStudents && !students.length && (
              <div
                style={{
                  margin: 12,
                  padding: '14px 12px',
                  textAlign: 'center',
                  borderRadius: 12,
                  border: `1px dashed ${colors.accent}44`,
                  background: `${colors.accent}0d`,
                }}>
                <i className="fas fa-user-friends" style={{ fontSize: 20, color: colors.accent }} />
                <div style={{ marginTop: 6, fontSize: 13, fontWeight: 'bold', color: colors.grey2 }}>
                  No students in this class
                </div>
              </div>
            )}
          </div>
        </Paper>

        {/* the chosen student: what was sent before, and a button to add a new one */}
        <Paper
          elevation={3}
          style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', borderRadius: 12, minHeight: 0 }}>
          {isLoadingStudents ? (
            <div style={{ padding: 24 }}>
              <SkeletonRows rows={4} />
            </div>
          ) : !student ? (
            <div style={{ margin: 'auto', padding: 40, textAlign: 'center', color: colors.grey3 }}>
              <ChatBubbleIcon style={{ fontSize: 44, color: `${colors.accent}55` }} />
              <div style={{ marginTop: 8, fontSize: 15, color: colors.grey2 }}>Pick a student</div>
              <div style={{ fontSize: 13 }}>to see the notes already sent about them and to add a new one.</div>
            </div>
          ) : (
            <>
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 12,
                  flexWrap: 'wrap',
                  padding: '14px 20px',
                  borderBottom: '1px solid #f0eaf5',
                }}>
                <Avatar name={student.firstName} size={44} active />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 17, fontWeight: 'bold' }}>{formStudentName(student)}</div>
                  <small className="text-muted">
                    Goes only to the guardian (a notification and their Parent notes list). Every note shows who wrote
                    it.
                  </small>
                </div>
                <CustomButton name="+ Add note" onClick={() => setIsFormOpen(true)} />
              </div>
              <div
                style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', padding: '12px 20px 4px' }}>
                <b style={{ fontSize: 15, marginRight: 6 }}>Earlier notes</b>
                {['ALL', ...KIND_KEYS].map(key => {
                  const selected = historyFilter === key;
                  const color = key === 'ALL' ? colors.accent : KINDS[key].color;
                  const count = key === 'ALL' ? history.length : counts[key] || 0;
                  return (
                    <button
                      key={key}
                      type="button"
                      onClick={() => setHistoryFilter(key)}
                      style={{
                        border: `1px solid ${selected ? color : '#e2d9ea'}`,
                        background: selected ? color : '#fff',
                        color: selected ? '#fff' : color,
                        borderRadius: 14,
                        padding: '1px 12px',
                        fontSize: 12,
                        fontWeight: 'bold',
                        cursor: 'pointer',
                      }}>
                      {key === 'ALL' ? 'All' : KINDS[key].label} {count}
                    </button>
                  );
                })}
              </div>
              {/* the list scrolls inside this box, so a long history never pushes the page */}
              <div
                ref={historyRef}
                style={{
                  flex: 1,
                  minHeight: 0,
                  overflowY: 'auto',
                  overscrollBehavior: 'contain',
                  padding: '8px 20px 16px',
                }}>
                {isLoadingHistory ? (
                  <SkeletonRows rows={4} />
                ) : shownHistory.length ? (
                  shownHistory.map(item => <HistoryItem key={item.feedbackId} item={item} />)
                ) : (
                  <div style={{ padding: 30, textAlign: 'center', color: colors.grey3, fontSize: 13 }}>
                    {history.length
                      ? 'Nothing of this kind yet.'
                      : `No note has been sent about ${student.firstName} yet. Use "+ Add note" to write the first one.`}
                  </div>
                )}
              </div>
            </>
          )}
        </Paper>
      </div>

      {/* the form opens on demand and closes once the feedback is sent */}
      <Modal isOpen={isFormOpen && !!student} toggle={() => !isSending && setIsFormOpen(false)} size="lg">
        <ModalHeader toggle={() => !isSending && setIsFormOpen(false)}>
          <span style={{ whiteSpace: 'nowrap' }}>Add note</span>
          <div className="text-muted" style={{ fontSize: 12, fontWeight: 'normal' }}>
            {student ? `About ${formStudentName(student)} · goes only to the guardian` : ''}
          </div>
        </ModalHeader>
        <ModalBody>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 12 }}>
            {KIND_KEYS.map(key => {
              const info = KINDS[key];
              const Icon = info.icon;
              const selected = kind === key;
              return (
                <button
                  key={key}
                  type="button"
                  onClick={() => setKind(key)}
                  style={{
                    flex: '1 1 140px',
                    textAlign: 'left',
                    cursor: 'pointer',
                    padding: '10px 12px',
                    borderRadius: 10,
                    border: `2px solid ${selected ? info.color : '#e6e0ec'}`,
                    background: selected ? `${info.color}14` : '#fff',
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                  }}>
                  <Icon style={{ color: info.color, fontSize: 22 }} />
                  <span>
                    <b style={{ display: 'block', fontSize: 13.5, color: selected ? info.color : colors.grey1 }}>
                      {info.label}
                    </b>
                    <small style={{ color: colors.grey3 }}>{info.hint}</small>
                  </span>
                </button>
              );
            })}
          </div>
          <CustomInput
            noLabel
            type="textarea"
            name="message"
            rows="5"
            placeholder="Write the note for the guardian..."
            value={message}
            onChange={(name, value) => setMessage(String(value).slice(0, MAX_CHARS))}
          />
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, margin: '4px 0 4px' }}>
            {kindInfo.phrases.map(phrase => (
              <button
                key={phrase}
                type="button"
                onClick={() => setMessage(prev => `${prev ? `${prev} ` : ''}${phrase}`.slice(0, MAX_CHARS))}
                style={{
                  border: `1px solid ${kindInfo.color}44`,
                  background: `${kindInfo.color}0f`,
                  color: kindInfo.color,
                  borderRadius: 14,
                  padding: '2px 10px',
                  fontSize: 12,
                  cursor: 'pointer',
                }}>
                + {phrase}
              </button>
            ))}
          </div>
          <div style={{ fontSize: 12, color: colors.grey3, textAlign: 'right' }}>
            {message.length}/{MAX_CHARS}
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            color="default"
            name="Cancel"
            disabled={isSending}
            onClick={() => setIsFormOpen(false)}
          />
          <CustomButton
            name="Send to guardian"
            onClick={send}
            disabled={!message.trim() || isSending}
            loading={isSending}
            showLoader={true}
          />
        </ModalFooter>
      </Modal>
    </div>
  );
};

export default StudentFeedbackPage;
