import React, { useEffect, useState } from 'react';
import CustomButton from 'components/CustomButton';
import EmptyState from 'views/admin/Common/EmptyState';
import { CommonLoader } from 'views/admin/Common/Loader';
import { fetchStudentFeedbackService } from 'actions/admin/feedback';
import { HistoryItem } from 'views/admin/StudentFeedback/StudentFeedbackPage';

const SHOWN = 5;

// The "Parent notes" tab of a student's page: the latest notes about this student with who wrote each and whether the guardian
// has read it, and "+ Add note", which opens the Parent notes page on this student with the form ready (the app's Student >
// Parent notes tab does the same). Read again whenever the student changes.
const StudentNotesPanel = ({ studentId, courseId, schoolId, token, history }) => {
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!studentId) return undefined;
    let cancelled = false;
    setNotes([]);
    setError('');
    setLoading(true);
    fetchStudentFeedbackService({ token, schoolId, studentId })
      .then(list => !cancelled && setNotes(list))
      .catch(() => !cancelled && setError('Could not load the notes'))
      .finally(() => !cancelled && setLoading(false));
    return () => {
      cancelled = true;
    };
  }, [studentId, schoolId, token]);

  const openPage = add =>
    history.push(`/admin/student-feedback?studentId=${studentId}&courseId=${courseId}${add ? '&add=1' : ''}`);

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8, marginBottom: 12 }}>
        <b>Parent notes{!loading && notes.length ? ` (${notes.length})` : ''}</b>
        <div style={{ display: 'flex', gap: 8 }}>
          {notes.length > SHOWN && (
            <CustomButton size="small" variant="outlined" name="See all" onClick={() => openPage(false)} />
          )}
          <CustomButton size="small" name="+ Add note" onClick={() => openPage(true)} />
        </div>
      </div>
      {loading ? (
        <CommonLoader />
      ) : error ? (
        <EmptyState icon="far fa-folder-open" title={error} />
      ) : notes.length ? (
        notes.slice(0, SHOWN).map(item => <HistoryItem key={item.feedbackId} item={item} />)
      ) : (
        <EmptyState
          icon="far fa-comment-dots"
          title="No notes yet"
          subtitle="Use + Add note to write the first one for this student's guardian."
        />
      )}
    </div>
  );
};

export default StudentNotesPanel;
