import React from 'react';
import Paper from '@material-ui/core/Paper';
import colors from 'config/colors';
import StatTile from 'views/admin/Common/StatTile';

// The look shared by the fee summary cards: a title with a status pill, rows of figures that all use the same type size,
// and an optional progress bar. Keeps the school-fee and transport-fee summaries consistent.
const FIGURE_SIZE = 20;

// One figure of the fee summary: the shared summary card (the App usage look), so every summary in the app reads the same.
export const Figure = ({ label, value, tone = 'neutral', note }) => (
  <StatTile label={label} value={value} tone={tone} note={note} minWidth={130} />
);

export const Operator = ({ symbol }) => (
  <div style={{ alignSelf: 'center', fontSize: FIGURE_SIZE, color: '#b0b0b0', fontWeight: 'bold' }} aria-hidden="true">
    {symbol}
  </div>
);

export const Row = ({ children }) => (
  <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'stretch', gap: 10, marginBottom: 12 }}>{children}</div>
);

// value/max fills the bar; `label` is the text above it
export const Progress = ({ value, max, label, color }) => {
  const percent = max > 0 ? Math.max(0, Math.min(100, Math.round((value / max) * 100))) : 0;
  return (
    <div>
      <div
        style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: '#7d7d7d', marginBottom: 4 }}>
        <span>{label}</span>
        <b style={{ color }}>{percent}%</b>
      </div>
      <div style={{ height: 8, borderRadius: 4, background: '#eceff1', overflow: 'hidden' }}>
        <div
          style={{ width: `${percent}%`, height: '100%', borderRadius: 4, background: color, transition: 'width .3s' }}
        />
      </div>
    </div>
  );
};

const SummaryCard = ({ title, status, children }) => (
  <Paper elevation={0} style={{ padding: 16, border: '3px solid #e0e0e0', marginBottom: 16 }}>
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, marginBottom: 12 }}>
      <div className="card-category font-weight-bold">{title}</div>
      {status && (
        <span
          style={{
            fontSize: 12,
            fontWeight: 'bold',
            color: status.color,
            background: `${status.color}1a`,
            borderRadius: 12,
            padding: '3px 12px',
          }}>
          {status.label}
        </span>
      )}
    </div>
    {children}
  </Paper>
);

export const accent = colors.accent;
export default SummaryCard;
