import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label } from 'reactstrap';
import Select from 'react-select';
import CustomButton from 'components/CustomButton';
import { selectStyle } from 'views/admin/Reports';
import { formResMessage } from 'utils/commonFunc';
import colors from 'config/colors';
import {
  fetchAllTransportGroupsPlainService,
  fetchTransportAreasPlainService,
  saveAssignedStudentsForTransportAreaService,
} from 'actions/admin/transportFee';

// Lets an admin assign an already-existing route/stop to a student right from the student's own
// Fees tab, instead of having to go find that student inside the Fees page's per-stop assign flow.
const AssignRouteModal = ({ isShow, hideForm, schoolId, batchId, studentId, loggedUserToken, onAssigned }) => {
  const [groups, setGroups] = useState([]);
  const [groupsLoading, setGroupsLoading] = useState(false);
  const [selectedGroupId, setSelectedGroupId] = useState(null);
  const [areas, setAreas] = useState([]);
  const [areasLoading, setAreasLoading] = useState(false);
  const [selectedAreaId, setSelectedAreaId] = useState(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!isShow) return;
    setSelectedGroupId(null);
    setSelectedAreaId(null);
    setAreas([]);
    setError('');
    setGroupsLoading(true);
    fetchAllTransportGroupsPlainService(schoolId, loggedUserToken)
      .then(rows => setGroups(rows || []))
      .catch(() => setError('Could not load routes'))
      .finally(() => setGroupsLoading(false));
  }, [isShow]);

  const groupOptions = groups.map(g => ({ value: g.transportFeeStructId, label: g.description }));
  const areaOptions = areas.map(a => ({ value: a.transportAreaId, label: `${a.areaName} (${a.distance} km)` }));

  const onGroupChange = dto => {
    setSelectedGroupId(dto.value);
    setSelectedAreaId(null);
    setAreas([]);
    setAreasLoading(true);
    fetchTransportAreasPlainService(dto.value, loggedUserToken)
      .then(rows => setAreas(rows || []))
      .catch(() => setError('Could not load destinations'))
      .finally(() => setAreasLoading(false));
  };

  const close = () => {
    setSaving(false);
    hideForm();
  };

  const handleAssign = async () => {
    if (!selectedGroupId || !selectedAreaId) {
      setError('Pick a route and a destination');
      return;
    }
    setSaving(true);
    try {
      await saveAssignedStudentsForTransportAreaService({
        students: [{ studentId }],
        transportFeeStructId: selectedGroupId,
        transportAreaId: selectedAreaId,
        schoolId,
        batchId,
        token: loggedUserToken,
      })();
      setSaving(false);
      close();
      onAssigned();
    } catch (err) {
      setSaving(false);
      setError(formResMessage(err));
    }
  };

  return (
    <Modal size="md" scrollable centered isOpen={isShow} className="modal-offset-sidebar">
      <ModalHeader toggle={close}>Assign Existing Route</ModalHeader>
      <ModalBody>
        {!!error && <div className="err-msg mb-2">{error}</div>}
        <Row>
          <Col md={12}>
            <div className="mb-3">
              <Label>
                Route<sup> *</sup>
              </Label>
              <Select
                name="transportGroup"
                isLoading={groupsLoading}
                options={groupOptions}
                value={groupOptions.find(el => el.value === selectedGroupId) || null}
                onChange={onGroupChange}
                styles={selectStyle(true)}
              />
            </div>
          </Col>
          <Col md={12}>
            <div className="mb-3">
              <Label>
                Destination<sup> *</sup>
              </Label>
              <Select
                name="transportArea"
                isLoading={areasLoading}
                isDisabled={!selectedGroupId}
                options={areaOptions}
                value={areaOptions.find(el => el.value === selectedAreaId) || null}
                onChange={dto => setSelectedAreaId(dto.value)}
                styles={selectStyle(true)}
              />
            </div>
          </Col>
        </Row>
      </ModalBody>
      <ModalFooter>
        <CustomButton className="mr-2" type="button" color="default" disabled={saving} onClick={close} name="Cancel" />
        <CustomButton
          type="button"
          name="Assign"
          disabled={saving}
          loading={saving}
          onClick={handleAssign}
          style={{ backgroundColor: colors.accent, color: colors.white }}
        />
      </ModalFooter>
    </Modal>
  );
};

export default AssignRouteModal;
