import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label } from 'reactstrap';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomButton from 'components/CustomButton';
import { formResMessage } from 'utils/commonFunc';
import colors from 'config/colors';

const MONTHS = [
  { label: 'January', value: 'JAN' },
  { label: 'February', value: 'FEB' },
  { label: 'March', value: 'MAR' },
  { label: 'April', value: 'APR' },
  { label: 'May', value: 'MAY' },
  { label: 'June', value: 'JUN' },
  { label: 'July', value: 'JUL' },
  { label: 'August', value: 'AUG' },
  { label: 'September', value: 'SEP' },
  { label: 'October', value: 'OCT' },
  { label: 'November', value: 'NOV' },
  { label: 'December', value: 'DEC' },
];

const monthLabel = value => MONTHS.find(m => m.value === value)?.label || value;

// paymentMonth is stored/sent as a single free-text String on the backend (e.g. "JAN"), so
// selecting several months here just joins them into one string like "JAN, FEB, MAR" - no
// backend change needed, it already accepts any string in that field.
const buildTransportNotes = months => (months.length ? `Transport fee for ${months.map(monthLabel).join(', ')}` : '');

const buildInitialState = defaultAmount => ({
  paymentMonth: '',
  amount: defaultAmount || 0,
  transactionId: '',
  notes: '',
});

const validateForm = data => {
  const errors = {};
  if (!data?.paymentMonth) {
    errors['paymentMonth'] = 'Payment month cannot be empty';
  }
  if (!data?.amount) {
    errors['amount'] = 'Amount cannot be empty';
  }
  return errors;
};

// One row = one paid month (or, via multi-select below, several months in one payment) for the
// student's current transport assignment. Unlike the fee-structure PaymentForm, there's no
// fee/status picker here - studentTransportId, transportAreaId etc. are fixed by whichever route
// the student is currently on, so the only choice the admin makes is which month(s) are covered.
const TransportPaymentForm = ({ isShow, defaultAmount, existingMonths = [], hideForm, onSave }) => {
  const [loading, setLoading] = useState(false);
  const [state, setState] = useState(buildInitialState(defaultAmount));
  const [errors, setError] = useState({});
  const [globalError, setGlobalError] = useState('');
  const [selectedMonths, setSelectedMonths] = useState([]);
  const [amountTouched, setAmountTouched] = useState(false);
  const [notesTouched, setNotesTouched] = useState(false);

  useEffect(() => {
    if (isShow) {
      setState(buildInitialState(defaultAmount));
      setError({});
      setGlobalError('');
      setLoading(false);
      setSelectedMonths([]);
      setAmountTouched(false);
      setNotesTouched(false);
    }
  }, [isShow]);

  const cancelPayment = () => {
    setState(buildInitialState(defaultAmount));
    setLoading(false);
    setSelectedMonths([]);
    setAmountTouched(false);
    setNotesTouched(false);
    hideForm();
  };

  const handleChange = (name, value) => {
    if (name === 'amount') setAmountTouched(true);
    if (name === 'notes') setNotesTouched(true);
    setState(prevState => ({ ...prevState, [name]: value }));
  };

  const applyMonths = nextMonths => {
    setSelectedMonths(nextMonths);
    setState(prevState => ({
      ...prevState,
      paymentMonth: nextMonths.join(', '),
      amount: amountTouched ? prevState.amount : Number(defaultAmount || 0) * nextMonths.length,
      notes: notesTouched ? prevState.notes : buildTransportNotes(nextMonths),
    }));
    setError(prevErrors => ({ ...prevErrors, paymentMonth: undefined }));
  };

  // Amount/notes stay auto-computed from the selection until the admin edits them directly -
  // once touched, further month toggles no longer overwrite that manual value.
  const toggleMonth = value => {
    applyMonths(selectedMonths.includes(value) ? selectedMonths.filter(m => m !== value) : [...selectedMonths, value]);
  };

  const selectAllMonths = () => applyMonths(MONTHS.map(m => m.value));
  const clearAllMonths = () => applyMonths([]);

  const handleSubmit = async e => {
    e.preventDefault();
    const error = validateForm(state);
    setError(error);
    if (!Object.keys(error)?.length) {
      setLoading(true);
      try {
        // BE fix: paymentDate must be sent as null - the server now stamps the payment with its
        // own current time instead of trusting a client-supplied date.
        await onSave({ ...state, amount: Number(state.amount), paymentDate: null });
        setLoading(false);
        setGlobalError('');
        cancelPayment();
      } catch (err) {
        setLoading(false);
        setGlobalError(formResMessage(err));
      }
    }
  };

  const alreadyPaidMonths = selectedMonths.filter(m => existingMonths.includes(m));
  const allSelected = selectedMonths.length === MONTHS.length;

  return (
    <Modal size="lg" scrollable centered isOpen={isShow} className="modal-offset-sidebar">
      <ModalHeader toggle={cancelPayment}>
        <span style={{ fontSize: 18, whiteSpace: 'nowrap' }}>Add Transport Payment</span>
      </ModalHeader>
      <form onSubmit={handleSubmit}>
        <ModalBody>
          {globalError && <div className="err-msg mb-2">{globalError}</div>}
          <Row>
            <Col md={12}>
              <div className="mb-3">
                <div
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'baseline',
                    flexWrap: 'wrap',
                  }}>
                  <Label style={{ marginBottom: 4 }}>
                    Payment month(s)
                    <sup> *</sup>{' '}
                    <span style={{ fontWeight: 400, color: '#5e6977', fontSize: 13 }}>
                      (select one or more &middot; ₹{Number(defaultAmount || 0)}/month)
                    </span>
                  </Label>
                  <span
                    onClick={allSelected ? clearAllMonths : selectAllMonths}
                    style={{ color: colors.accent, fontSize: 13, fontWeight: 'bold', cursor: 'pointer' }}>
                    {allSelected ? 'Clear all' : 'Select all'}
                  </span>
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                  {MONTHS.map(month => {
                    const selected = selectedMonths.includes(month.value);
                    const paid = existingMonths.includes(month.value);
                    return (
                      <div
                        key={month.value}
                        onClick={() => toggleMonth(month.value)}
                        style={{
                          cursor: 'pointer',
                          userSelect: 'none',
                          padding: '8px 12px',
                          borderRadius: 8,
                          border: `2px solid ${selected ? colors.accent : '#e0e0e0'}`,
                          backgroundColor: selected ? `${colors.accent}14` : '#fff',
                          fontSize: 13,
                          fontWeight: selected ? 'bold' : 'normal',
                        }}>
                        {month.label}
                        {paid && <span style={{ marginLeft: 6, fontSize: 10, color: '#c67c00' }}>&#9679; paid</span>}
                      </div>
                    );
                  })}
                </div>
                {errors.paymentMonth && <span className="err-msg">{errors.paymentMonth}</span>}
                {!errors.paymentMonth && !!alreadyPaidMonths.length && (
                  <div style={{ color: '#c67c00', fontSize: 12, marginTop: 4 }}>
                    A payment for {alreadyPaidMonths.map(monthLabel).join(', ')} is already recorded - saving will add
                    another one.
                  </div>
                )}
                {!!selectedMonths.length && (
                  <div style={{ fontSize: 12, color: '#6b778a', marginTop: 6 }}>
                    Selected: {selectedMonths.map(monthLabel).join(', ')} ({selectedMonths.length} month
                    {selectedMonths.length > 1 ? 's' : ''}) &middot; Suggested total: ₹
                    {Number(defaultAmount || 0) * selectedMonths.length}
                  </div>
                )}
              </div>
            </Col>
            <Col md={6}>
              <CustomInput
                label={
                  <>
                    Amount<sup> *</sup>
                  </>
                }
                name="amount"
                value={state.amount}
                onChange={handleChange}
                error={errors.amount}
              />
            </Col>
            <Col md={6}>
              <CustomInput
                label="Transaction Id"
                name="transactionId"
                value={state.transactionId}
                onChange={handleChange}
                error={errors?.transactionId}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                label="Notes"
                name="notes"
                type="textarea"
                placeholder="Optional notes about this payment..."
                value={state.notes}
                onChange={handleChange}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={cancelPayment}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Save"
            disabled={loading}
            loading={loading}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default TransportPaymentForm;
