import axios from 'axios';
import constants from 'config/constants';

// Feedback about one student from a teacher or admin. `type` is POSITIVE, NEUTRAL or NEGATIVE. The backend sends it only to
// that student's guardian (push notification + the guardian's own notification list) and keeps it for the staff.
export const sendStudentFeedbackService = ({ token, schoolId, studentId, type, message }) =>
  axios.post(
    `${constants.API_BASE_URL}/api/user/student-feedback/${schoolId}/${studentId}`,
    { type, message },
    constants.setHeader(token)
  );

// What was already sent about the student, newest first: [{ feedbackId, kind, message, fromUserName, fromUserRole, creationDateTime }]
export const fetchStudentFeedbackService = async ({ token, schoolId, studentId }) => {
  const res = await axios.get(
    `${constants.API_BASE_URL}/api/user/student-feedback/${schoolId}/${studentId}`,
    constants.setHeader(token)
  );
  return res.data || [];
};
