import React from 'react';
import Paper from '@material-ui/core/Paper';
import { makeStyles, useTheme } from '@material-ui/core/styles';
import Tabs from '@material-ui/core/Tabs';
import Tab from '@material-ui/core/Tab';
import { a11yProps } from 'views/admin/MyProfile';
import { CommonLoader } from 'views/admin/Common/Loader';
import { ScrollTabPanel } from 'views/admin/Reports';
import Grid from '@material-ui/core/Grid';
import { courseStatic, formStudentName, regNoStatic } from 'config/constants';
import StudentStatusTag from 'views/admin/Common/StudentStatusTag';
import { studentStatusLabel } from 'utils/studentStatus';
import moment from 'moment';
import { isWeb, makeSubstring, makeSubText, toTitleCase } from 'utils/commonFunc';
import CustomButton from 'components/CustomButton';
import ArrowBackIcon from '@material-ui/icons/ArrowBack';
import AccountCircleIcon from '@material-ui/icons/AccountCircle';
import CommonTooltip from 'views/admin/Common/CommonTooltip';
import { Row, Col } from 'reactstrap';
import ActivityList from 'views/admin/Activities/ActivityList';
import { Pagination, PaginationItem, PaginationLink } from 'reactstrap';
import colors from 'config/colors';
import StudentFeesPanel from './StudentFeesPanel.jsx';
import StudentProgressPanel from './StudentProgressPanel';
import StudentNotesPanel from './StudentNotesPanel.jsx';
import LoadMore from 'views/admin/EmployeeActivities/components/LoadMore';
import EmptyState from 'views/admin/Common/EmptyState';

const useStyles = makeStyles(() => ({
  root: {
    flexGrow: 1,
  },
}));

// Billings used to be its own top-level tab - it now lives as a sub-tab of Fees & Bills (see
// StudentFeesPanel.jsx), alongside the new School Fee / Transport Fee split.
const tabHeaders = [
  { label: 'Basic Info', key: 'profile' },
  { label: 'Activities', key: 'activities' },
  { label: 'Home Works', key: 'homework' },
  { label: 'Assignments', key: 'assignments' },
  { label: 'Parent notes', key: 'notes' },
  { label: 'Fees & Bills', key: 'fees' },
];

// Home work and assignments newest first, with the month (and, for assignments, the day) over its cards - the same as the app.
const newestFirst = list =>
  [...(list || [])].sort((a, b) => moment(b.creationDateTime).valueOf() - moment(a.creationDateTime).valueOf());

const DateHeadings = ({ list, index, byDay }) => {
  const date = moment(list[index].creationDateTime);
  const prev = index > 0 ? moment(list[index - 1].creationDateTime) : null;
  const newMonth = !prev || !prev.isSame(date, 'month');
  const newDay = byDay && (!prev || !prev.isSame(date, 'day'));
  return (
    <>
      {newMonth && (
        <Grid item xs={12}>
          <div
            style={{
              backgroundColor: '#FAF5FD',
              color: colors.accent,
              fontSize: 12,
              fontWeight: 'bold',
              letterSpacing: 0.6,
              padding: '5px 12px',
              borderRadius: 8,
              marginTop: index ? 6 : 0,
            }}>
            {date.format('MMMM YYYY').toUpperCase()}
          </div>
        </Grid>
      )}
      {newDay && (
        <Grid item xs={12}>
          <div style={{ color: '#6b778a', fontSize: 12, fontWeight: 'bold', padding: '0 4px' }}>
            {date.format('dddd, D MMMM')}
          </div>
        </Grid>
      )}
    </>
  );
};

const LIST_PAGE = 20;

export default function StudentDetailView(props) {
  const {
    onBack,
    profileFetching,
    homeworkFetching,
    assignmentsFetching,
    fetchInfo,
    payStudentFeePayment,
    updateSuccess,
    feeStructureFetching,
    paymentsFetching,
    studentReducer,
    activitiesFetching,
    fetchandShowFeesReceiptReport,
    refundsByStudent,
    fetchRefundsForStudentBatch,
    refundsByPayment,
    refundTotalByPayment,
    fetchRefundsForPayment,
    fetchRefundTotalForPayment,
    createRefund,
  } = props;
  const classes = useStyles();
  const theme = useTheme();
  // Tab lives in the URL (?tab=fees) so navigating away (e.g. to create a route/fee structure
  // and back) or refreshing lands back on the same tab instead of always resetting to Basic Info.
  const [value, setTab] = React.useState(() => {
    const tabKey = new URLSearchParams(props.location?.search).get('tab');
    const index = tabHeaders.findIndex(t => t.key === tabKey);
    return index >= 0 ? index : 0;
  });
  // ActivityList's "Show" dropdown only offers 10/50/100/200/500 - a limit of 20 matches none of
  // them, so MUI's Select rendered blank instead of showing a selected value.
  const [pageLimit, setPageLimit] = React.useState({ page: 1, limit: 10 });
  const { lastFetch, profile, homework, assignments, feeStructure, payments, activities } = studentReducer;
  // how many of the latest home work / assignments are listed; "Load more" raises it
  const [homeworkLimit, setHomeworkLimit] = React.useState(LIST_PAGE);
  const [assignmentLimit, setAssignmentLimit] = React.useState(LIST_PAGE);
  const studentId = profile.studentId;
  const courseId = profile.currentCourse?.courseId;

  // The audit log has no studentId column to filter on. A student's activity is spread over several modules (profile edits,
  // fee payments, exams ...), so no module filter is used; instead the log lines that name the student are matched
  // (auditDescription is a LIKE match). firstName alone, rather than the full "first middle last" the backend
  // concatenates, sidesteps a real BE quirk: a null middleName gets concatenated as the literal text "null" in that
  // stored string, which would break a match built from firstName+lastName together.
  const auditChangesFor = profile.firstName || '';

  const handleLimitChange = e => {
    const limit = e.target.value;
    setPageLimit(prevState => ({ ...prevState, page: 1, limit }));
    fetchInfo('activities', {
      studentId,
      filterData: { page: 1, limit, auditDescription: auditChangesFor },
    });
  };

  const handleChange = (event, newValue) => {
    if (!profileFetching) {
      if (['activities', 'appreciations'].includes(tabHeaders[newValue].key)) {
        fetchInfo(tabHeaders?.[newValue]?.key, {
          studentId,
          filterData: { ...pageLimit, auditDescription: auditChangesFor },
        });
      } else if (['homework', 'assignments'].includes(tabHeaders[newValue].key)) {
        const lastFetchTime = lastFetch[tabHeaders?.[newValue]?.key];
        if (
          !props?.[`${tabHeaders?.[newValue]?.key}Fetching`] &&
          (!Object.keys(studentReducer?.[tabHeaders?.[newValue]?.key])?.length ||
            new Date() > moment(lastFetchTime).add(3, 'hours'))
        ) {
          fetchInfo(tabHeaders?.[newValue]?.key, { studentId, courseId });
        }
      }
      setTab(newValue);
      if (props.history && props.location) {
        props.history.push(`${props.location.pathname}?tab=${tabHeaders[newValue].key}`);
      }
    }
  };

  const loaderDiv = (
    <div style={{ textAlign: 'center', padding: 30 }}>
      <CommonLoader />
    </div>
  );

  const guardianKeys = {
    guardName: { label: 'Name', value: profile.guardName },
    guardEmail: { label: 'Email', value: profile.guardEmail },
    guardianMobile: { label: 'Mobile', value: profile.guardianMobile },
    guardianEducation: { label: 'Education', value: profile.guardianEducation },
    guardianOccupation: { label: 'Occupation', value: profile.guardianOccupation },
    relation: { label: 'Relation', value: profile.relation },
  };
  const guardianData = (
    <Grid container spacing={2}>
      {Object.keys(guardianKeys)?.map((keyElement, k) => {
        return (
          <React.Fragment key={k}>
            <Grid item xs={2}>
              <p>
                <b>{guardianKeys[keyElement]?.label}</b>
              </p>
            </Grid>
            <Grid item xs={4}>
              <p className="card-category">{guardianKeys[keyElement]?.value || '--'}</p>
            </Grid>
          </React.Fragment>
        );
      })}
    </Grid>
  );

  const profileKeys = {
    currentBatch: {
      label: 'Batch',
      value: profile.currentBatch?.name || `${profile?.currentBatch?.startYear} - ${profile?.currentBatch?.endYear}`,
    },
    currentCourse: { label: courseStatic, value: profile.currentCourse?.name, code: profile?.currentCourse?.code },
    fullName: { label: 'Full Name', value: formStudentName(profile) },
    registerNumber: { label: regNoStatic, value: profile.registerNumber },
    email: { label: 'Email', value: profile.email },
    dateOfBirth: { label: 'Date of birth', value: moment(profile?.dateOfBirth).format('DD MMM, YYYY') },
    gender: { label: 'Gender', value: profile.gender },
    bloodGroup: { label: 'Blood group', value: profile.bloodGroup },
    joiningDateTime: { label: 'Joining date', value: moment(profile?.joiningDateTime).format('DD MMM, YYYY') },
    motherTongue: { label: 'Mother tongue', value: profile.motherTongue },
    nationality: { label: 'Nationality', value: profile.nationality },
    hostel: { label: 'Staying in Hostel', value: profile.hostel ? 'Yes' : 'No' },
    status: { label: 'Status', value: studentStatusLabel(profile.status) || profile.status || 'Active' },
    birthPlace: { label: 'Birth place', value: profile.birthPlace },
  };

  const profileData = (
    <>
      <Grid container spacing={2}>
        {Object.keys(profileKeys)?.map((keyElement, k) => {
          return (
            <React.Fragment key={k}>
              {/* Two label+value pairs share a row (2+4=6 of 12 cols) from sm up, matching
                  the existing desktop layout - but at xs that same split crams both pairs
                  onto one row regardless of screen width, which is what was forcing labels
                  like "Staying in Hostel" to wrap across 3 lines on a phone. Below sm, each
                  pair gets the full row (4+8=12) instead. */}
              <Grid item xs={4} sm={2}>
                <p>
                  <b>{profileKeys[keyElement]?.label}</b>
                </p>
              </Grid>
              <Grid item xs={8} sm={4}>
                <p className="card-category">{profileKeys[keyElement]?.value || '--'}</p>
              </Grid>
            </React.Fragment>
          );
        })}
      </Grid>
      <p style={{ margin: '5px 0px 15px', color: '#9a9a9a', fontWeight: 'bold' }}>Guardian</p>
      {guardianData}
    </>
  );

  // TaskDto/StudentAssignmentDto both already carry this student's own status for that item (the
  // /task-recent and /assignment-recent endpoints are student-scoped), matching the badge the
  // mobile app shows - just needed rendering here, no new fetch.
  const statusBadge = status => {
    if (!status) return null;
    const style = {
      PENDING: { background: '#FFF3E0', color: '#e65100' },
      INPROGRESS: { background: '#E3F2FD', color: '#1565c0' },
      COMPLETED: { background: '#E8F5E9', color: '#2e7d32' },
    }[status] || { background: '#eee', color: '#616161' };
    return (
      <span
        style={{
          display: 'inline-block',
          fontSize: 10,
          fontWeight: 'bold',
          borderRadius: 4,
          padding: '2px 6px',
          marginTop: 4,
          ...style,
        }}>
        {status === 'INPROGRESS' ? 'IN PROGRESS' : status}
      </span>
    );
  };

  const homeWorkDiv =
    homework?.length > 0 ? (
      <>
        <Grid container spacing={1}>
          {newestFirst(homework).map((dto, k, sorted) => {
            return (
              <React.Fragment key={k}>
                <DateHeadings list={sorted} index={k} />
                <Grid item sm={12} md={6} xs={12}>
                  <div
                    style={{
                      display: 'flex',
                      borderRadius: 12,
                      overflow: 'hidden',
                      marginBottom: 8,
                      boxShadow: '0 1px 4px rgba(0,0,0,0.08)',
                      backgroundColor: colors.white,
                    }}>
                    <div style={{ width: 5, backgroundColor: colors.accent, flexShrink: 0 }} />
                    <div style={{ flex: 1, padding: '12px 14px' }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                        <span
                          style={{
                            display: 'inline-block',
                            backgroundColor: '#F5EDFB',
                            color: colors.accent,
                            fontSize: 11,
                            fontWeight: 'bold',
                            borderRadius: 6,
                            padding: '3px 8px',
                          }}>
                          {dto.subject?.name} ({dto?.subject?.subjectCode})
                        </span>
                        <div style={{ textAlign: 'right', marginLeft: 8 }}>
                          <small style={{ color: '#9a9a9a', whiteSpace: 'nowrap' }}>
                            {moment(new Date(dto?.creationDateTime)).format('DD MMM, YYYY')}
                          </small>
                          <div>{statusBadge(dto.status)}</div>
                        </div>
                      </div>
                      <div style={{ fontWeight: 'bold', fontSize: 15, marginTop: 8 }}>{dto.name}</div>
                      <div style={{ fontSize: 13, color: '#6b778a', marginTop: 2 }}>
                        <CommonTooltip content={dto.description}>
                          <span>{makeSubstring(dto?.description, 70)}</span>
                        </CommonTooltip>
                      </div>
                      <div
                        style={{
                          display: 'flex',
                          justifyContent: 'space-between',
                          alignItems: 'flex-end',
                          marginTop: 6,
                        }}>
                        {!!dto.timePeriod && (
                          <div style={{ fontSize: 12, color: '#9a9a9a' }}>Period: {dto.timePeriod}</div>
                        )}
                        {!!dto.createdUser?.name && (
                          <div style={{ fontSize: 12, color: '#9a9a9a' }}>By {toTitleCase(dto.createdUser.name)}</div>
                        )}
                      </div>
                    </div>
                  </div>
                </Grid>
              </React.Fragment>
            );
          })}
        </Grid>
        <LoadMore
          visible={homework.length >= homeworkLimit}
          loading={homeworkFetching}
          onClick={() => {
            const next = homeworkLimit + LIST_PAGE;
            setHomeworkLimit(next);
            fetchInfo('homework', { studentId, courseId, limit: next });
          }}
        />
      </>
    ) : (
      <>
        <EmptyState compact bare icon="far fa-folder-open" title="Nothing to show here yet" />
        <div style={{ textAlign: 'center' }} className="mt-4">
          <CustomButton
            size="small"
            variant="outlined"
            onClick={() => props.history.push('/admin/employee-activities?home-work')}
            name={`Go to ${courseStatic} homework page`}
          />
        </div>
      </>
    );

  const assignmentDiv =
    assignments?.length > 0 ? (
      <>
        <Grid container spacing={1}>
          {newestFirst(assignments).map((dto, k, sorted) => {
            const priorityColor = { HIGH: '#e53935', MEDIUM: '#f9a825', LOW: '#43a047' }[dto.priority];
            return (
              <React.Fragment key={k}>
                <DateHeadings list={sorted} index={k} byDay />
                <Grid item sm={12} md={6} xs={12}>
                  <div
                    style={{
                      display: 'flex',
                      borderRadius: 12,
                      overflow: 'hidden',
                      marginBottom: 8,
                      boxShadow: '0 1px 4px rgba(0,0,0,0.08)',
                      backgroundColor: colors.white,
                    }}>
                    <div style={{ width: 5, backgroundColor: colors.accent, flexShrink: 0 }} />
                    <div style={{ flex: 1, padding: '12px 14px' }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                        <span
                          style={{
                            display: 'inline-block',
                            backgroundColor: '#F5EDFB',
                            color: colors.accent,
                            fontSize: 11,
                            fontWeight: 'bold',
                            borderRadius: 6,
                            padding: '3px 8px',
                          }}>
                          {dto.subject?.name} ({dto?.subject?.subjectCode})
                        </span>
                        <div style={{ textAlign: 'right', marginLeft: 8 }}>
                          {!!dto.priority && (
                            <div style={{ color: priorityColor, fontWeight: 'bold', fontSize: 11 }}>{dto.priority}</div>
                          )}
                          <small style={{ color: '#9a9a9a', whiteSpace: 'nowrap' }}>
                            {moment(new Date(dto?.creationDateTime)).format('DD MMM, YYYY')}
                          </small>
                          <div>{statusBadge(dto.status)}</div>
                        </div>
                      </div>
                      <div style={{ fontWeight: 'bold', fontSize: 15, marginTop: 8 }}>{dto.title}</div>
                      <div style={{ fontSize: 13, color: '#6b778a', marginTop: 2 }}>
                        <CommonTooltip content={dto.description}>
                          <span>{makeSubstring(dto?.description, 70)}</span>
                        </CommonTooltip>
                      </div>
                      <div
                        style={{
                          display: 'flex',
                          justifyContent: 'space-between',
                          alignItems: 'flex-end',
                          marginTop: 6,
                        }}>
                        <div style={{ fontSize: 12, color: '#9a9a9a' }}>
                          Last date to submit: {moment(new Date(dto?.submissionDate)).format('DD MMM, YYYY')}
                        </div>
                        {!!dto.createdUser?.name && (
                          <div style={{ fontSize: 12, color: '#9a9a9a' }}>By {toTitleCase(dto.createdUser.name)}</div>
                        )}
                      </div>
                    </div>
                  </div>
                </Grid>
              </React.Fragment>
            );
          })}
        </Grid>
        <LoadMore
          visible={assignments.length >= assignmentLimit}
          loading={assignmentsFetching}
          onClick={() => {
            const next = assignmentLimit + LIST_PAGE;
            setAssignmentLimit(next);
            fetchInfo('assignments', { studentId, courseId, limit: next });
          }}
        />
      </>
    ) : (
      <>
        <EmptyState compact bare icon="far fa-folder-open" title="Nothing to show here yet" />
        <div style={{ textAlign: 'center' }} className="mt-4">
          <CustomButton
            size="small"
            variant="outlined"
            onClick={() => props.history.push('/admin/employee-activities?home-work')}
            name={`Go to ${courseStatic} assignment page`}
          />
        </div>
      </>
    );

  const activitiesDiv = (
    <>
      <ActivityList
        activities={activities}
        handleLimitChange={handleLimitChange}
        limit={pageLimit.limit}
        showLimitAlways={true}
      />
      {!!activities?.length && (
        <div>
          <Pagination aria-label="Page navigation example" style={{ textAlign: 'center', justifyContent: 'center' }}>
            <PaginationItem>
              <PaginationLink
                href="#"
                previous
                onClick={() => {
                  if (pageLimit?.page > 1 && !activitiesFetching) {
                    setPageLimit(prevState => ({ ...prevState, page: pageLimit?.page - 1 }));
                    fetchInfo('activities', {
                      studentId,
                      filterData: {
                        page: pageLimit?.page - 1,
                        limit: pageLimit?.limit,
                        auditDescription: auditChangesFor,
                      },
                    });
                  }
                }}
              />
            </PaginationItem>
            <PaginationItem>
              <PaginationLink href="#">{pageLimit?.page}</PaginationLink>
            </PaginationItem>
            <PaginationItem>
              <PaginationLink
                href="#"
                next
                onClick={() => {
                  if (!activitiesFetching && activities?.length >= 10) {
                    setPageLimit(prevState => ({ ...prevState, page: pageLimit?.page + 1 }));
                    fetchInfo('activities', {
                      studentId,
                      filterData: {
                        page: pageLimit?.page + 1,
                        limit: pageLimit?.limit,
                        auditDescription: auditChangesFor,
                      },
                    });
                  }
                }}
              />
            </PaginationItem>
          </Pagination>
        </div>
      )}
      <div style={{ textAlign: 'center' }} className="mt-4">
        <CustomButton
          size="small"
          variant="outlined"
          onClick={() => props.history.push('/admin/school-activities?all-activities')}
          name={`Go to Activities page`}
        />
      </div>
    </>
  );

  const renderItems = {
    profile: (
      <>
        {profileFetching ? (
          loaderDiv
        ) : (
          <>
            <StudentProgressPanel studentId={studentId} token={props.loggedUserToken} profile={profile} />
            <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
              {profileData}
            </Paper>
          </>
        )}
      </>
    ),
    homework: <>{homeworkFetching ? loaderDiv : <div>{homeWorkDiv}</div>}</>,
    assignments: <>{assignmentsFetching ? loaderDiv : <div>{assignmentDiv}</div>}</>,
    fees: (
      <div>
        <StudentFeesPanel
          studentId={studentId}
          courseId={courseId}
          loggedUserSchool={props.loggedUserSchool}
          loggedUserToken={props.loggedUserToken}
          feeStructureFetching={feeStructureFetching}
          paymentsFetching={paymentsFetching}
          feeStructure={feeStructure}
          payments={payments}
          fetchInfo={fetchInfo}
          payStudentFeePayment={payStudentFeePayment}
          updateSuccess={updateSuccess}
          fetchandShowFeesReceiptReport={fetchandShowFeesReceiptReport}
          refundsByStudent={refundsByStudent}
          fetchRefundsForStudentBatch={fetchRefundsForStudentBatch}
          refundsByPayment={refundsByPayment}
          refundTotalByPayment={refundTotalByPayment}
          fetchRefundsForPayment={fetchRefundsForPayment}
          fetchRefundTotalForPayment={fetchRefundTotalForPayment}
          createRefund={createRefund}
        />
      </div>
    ),
    notes: (
      <StudentNotesPanel
        studentId={studentId}
        courseId={courseId}
        schoolId={props.loggedUserSchool}
        token={props.loggedUserToken}
        history={props.history}
      />
    ),
    activities: <>{activitiesFetching ? loaderDiv : <div>{activitiesDiv}</div>}</>,
  };

  return (
    <div className="content">
      <Row className="mb-2">
        <Col md={1} sm={1} xs={2} lg={1}>
          <CommonTooltip content="Back to students">
            <span>
              <ArrowBackIcon fontSize="large" style={{ fontSize: 34, cursor: 'pointer' }} onClick={onBack} />
            </span>
          </CommonTooltip>
        </Col>
        <Col md={1} sm={1} xs={2} lg={1}>
          <AccountCircleIcon fontSize="large" style={{ fontSize: 60 }} />
        </Col>
        <Col>
          {profile?.studentId ? (
            <>
              <div className="card-category mt-1">
                <span style={{ fontSize: 16 }}>
                  <b>{profileKeys.fullName?.value}</b>
                </span>{' '}
                {makeSubText(profileKeys.registerNumber?.value, { fontSize: 16 })}
              </div>
              <div className="card-category mt-1">
                {profileKeys.currentCourse.value}{' '}
                {makeSubText(profileKeys.currentCourse.code, { dontMakeBold: true, fontSize: 13 })}
              </div>
            </>
          ) : (
            <CommonLoader size={10} />
          )}
        </Col>
        {profile?.studentId && (
          <Col xs="auto" className="ml-auto">
            <StudentStatusTag status={profile.status} style={{ fontSize: 13, padding: '4px 12px' }} />
          </Col>
        )}
      </Row>
      <Paper square className={classes.root} elevation={5}>
        <Tabs
          value={value}
          onChange={handleChange}
          variant={isWeb ? 'fullWidth' : 'scrollable'}
          // "auto" hides the arrows on touch devices, assuming a swipe - but with 5 tabs
          // on a phone-width screen the row just gets truncated mid-label ("Assig...")
          // with nothing to signal there's more to see. Forcing them "on" keeps a visible
          // affordance for non-technical users who won't think to try swiping.
          scrollButtons="on"
          indicatorColor=""
          textColor="inherit"
          aria-label="icon label tabs example">
          {tabHeaders.map((tab, i) => (
            <Tab
              key={i}
              label={tab.label}
              {...a11yProps(i)}
              style={{
                fontWeight: 'bold',
                color: value === i ? colors.accent : '',
                borderBottom: value === i ? `3px solid ${colors.accent}` : '',
              }}
            />
          ))}
        </Tabs>
      </Paper>
      <ScrollTabPanel value={value} index={value} dir={theme.direction} style={{ padding: '25px 0px 10px 0px' }}>
        <div style={{ margin: 5 }}>{renderItems[tabHeaders[value].key]}</div>
      </ScrollTabPanel>
    </div>
  );
}
