import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Table, Label } from 'reactstrap';
import Select from 'react-select';
import CustomButton from 'components/CustomButton';
import CustomInput from 'views/admin/Common/CustomInput';
import { CommonLoader } from 'views/admin/Common/Loader';
import { formResMessage, formatMoney } from 'utils/commonFunc';
import { selectStyle } from 'views/admin/Reports';
import colors from 'config/colors';
import moment from 'moment';

const refundModes = [
  { label: 'Cash', value: 'CASH' },
  { label: 'UPI', value: 'UPI' },
  { label: 'Bank Transfer', value: 'BANK_TRANSFER' },
  { label: 'Payment Gateway', value: 'PAYMENT_GATEWAY' },
];

const PaymentRefundModal = ({
  isOpen,
  onClose,
  payment,
  refunds = [],
  totalRefunded = 0,
  isFetching = false,
  onFetch,
  onSubmit,
  showWarning,
}) => {
  const [amount, setAmount] = useState('');
  const [reason, setReason] = useState('');
  const [refundMode, setRefundMode] = useState(null);
  const [error, setError] = useState('');
  const [modeError, setModeError] = useState('');
  const [reasonError, setReasonError] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  const remaining = Number(payment?.amount || 0) - Number(totalRefunded || 0);

  useEffect(() => {
    if (isOpen && payment) {
      setAmount('');
      setReason('');
      setRefundMode(null);
      setError('');
      setModeError('');
      setReasonError('');
      setIsSaving(false);
      onFetch(payment.studPaymentId);
    }
  }, [isOpen, payment?.studPaymentId]);

  const handleSubmit = e => {
    e.preventDefault();
    const numAmount = Number(amount);
    let hasError = false;
    if (!numAmount || numAmount <= 0) {
      setError('Enter a valid amount');
      hasError = true;
    } else if (numAmount > remaining) {
      setError(`Cannot exceed the refundable amount (${formatMoney(remaining)})`);
      hasError = true;
    } else {
      setError('');
    }
    if (!refundMode) {
      setModeError('Select a refund mode');
      hasError = true;
    } else {
      setModeError('');
    }
    if (!reason?.trim()) {
      setReasonError('Reason is required');
      hasError = true;
    } else {
      setReasonError('');
    }
    if (hasError) return;
    setIsSaving(true);
    onSubmit({
      studPaymentId: payment?.studPaymentId,
      refundAmount: numAmount,
      refundMode: refundMode.value,
      refundReason: reason.trim(),
    })
      .then(() => {
        setIsSaving(false);
        setAmount('');
        setReason('');
        setRefundMode(null);
      })
      .catch(err => {
        setIsSaving(false);
        showWarning?.(formResMessage(err), 'error');
      });
  };

  return (
    <Modal size="lg" scrollable centered isOpen={isOpen} className="modal-offset-sidebar">
      <ModalHeader toggle={onClose}>Refund Payment</ModalHeader>
      <form onSubmit={handleSubmit}>
        <ModalBody>
          <div style={{ fontSize: 13, marginBottom: 5 }}>
            {payment?.feeDescription} &middot; Paid {formatMoney(payment?.amount)}
          </div>
          {isFetching ? (
            <CommonLoader />
          ) : (
            <>
              <div style={{ fontSize: 13, marginBottom: 10, color: '#6b778a' }}>
                Refunded so far: <b>{formatMoney(totalRefunded)}</b> &middot; Refundable up to:{' '}
                <b>{formatMoney(remaining)}</b>
              </div>
              {!!refunds.length && (
                <Table size="sm" className="mb-3">
                  <thead>
                    <tr>
                      <th>Date</th>
                      <th>Amount</th>
                      <th>Mode</th>
                      <th>Reason</th>
                    </tr>
                  </thead>
                  <tbody>
                    {refunds.map(item => (
                      <tr key={item.refundId}>
                        <td>{item.refundDate ? moment(item.refundDate).format('DD MMM, YYYY') : '--'}</td>
                        <td>{formatMoney(item.refundAmount)}</td>
                        <td>{item.refundMode || '--'}</td>
                        <td>{item.refundReason || '--'}</td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              )}
              <Row>
                <Col md={12}>
                  <CustomInput
                    type="number"
                    label="Refund amount"
                    name="amount"
                    placeholder="Enter amount"
                    value={amount}
                    onChange={(name, value) => setAmount(value)}
                    error={error}
                    disabled={remaining <= 0}
                  />
                </Col>
                <Col md={12}>
                  <div className="mb-3">
                    <Label>Refund mode</Label>
                    <Select
                      name="refundMode"
                      options={refundModes}
                      value={refundMode}
                      onChange={setRefundMode}
                      styles={selectStyle(!modeError)}
                      isDisabled={remaining <= 0}
                    />
                    {modeError && <span className="err-msg">{modeError}</span>}
                  </div>
                </Col>
                <Col md={12}>
                  <CustomInput
                    label="Reason"
                    name="reason"
                    placeholder="Enter reason"
                    value={reason}
                    onChange={(name, value) => setReason(value)}
                    error={reasonError}
                    disabled={remaining <= 0}
                  />
                </Col>
              </Row>
              {remaining <= 0 && (
                <div style={{ fontSize: 12, color: '#9a9a9a' }}>This payment has already been fully refunded.</div>
              )}
            </>
          )}
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={isSaving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            loading={isSaving}
            disabled={isSaving || isFetching || remaining <= 0}
            name="Refund"
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default PaymentRefundModal;
