import axios from 'axios';
import constants from 'config/constants';

// Transport fee is monthly, not a one-off fee-structure line, so it can't reuse the generic
// fee-structure payment API - the backend added a dedicated StudentTransportPayment endpoint
// (one row per student per paid month) for it instead. Plain async calls (no thunk/reducer),
// matching how StudentDetailView already reads the adjacent transport-area data.
const API = '/api/transport/payment';

const BASE = constants.API_BASE_URL;

export const fetchTransportPaymentsByStudentService = async (studentId, token) => {
  const res = await axios.get(`${BASE}${API}/student/${studentId}`, constants.setHeader(token));
  return res.data;
};

export const createTransportPaymentService = async (postData, token) => {
  // paymentDate is always null: the server stamps the payment with its own date-time.
  const res = await axios.post(`${BASE}${API}`, { ...postData, paymentDate: null }, constants.setHeader(token));
  return res.data;
};
