import React, { useEffect, useState } from 'react';
import Paper from '@material-ui/core/Paper';
import SentimentSatisfiedAltIcon from '@material-ui/icons/SentimentSatisfiedAlt';
import SentimentDissatisfiedIcon from '@material-ui/icons/SentimentDissatisfied';
import StatTile, { TONE_COLORS } from 'views/admin/Common/StatTile';
import { fetchStudentContactsApi, fetchStudentProgressApi } from 'actions/admin/students';
import { computeStudentCompletion } from 'utils/studentCompletion';
import { getGlobalCurrentBatchUtils } from 'utils/commonFunc';

// Share of the way to "good" for a percentage: green from 75, amber from 50, red below.
const toneFor = percent => (percent >= 75 ? 'good' : percent >= 50 ? 'warn' : 'bad');
// a neutral face (Material UI v4 has no flat-mouth one)
const NeutralFaceIcon = ({ style }) => (
  <svg viewBox="0 0 24 24" width="18" height="18" style={style} fill="currentColor" aria-hidden="true">
    <path d="M9 14h6v1.5H9zM15.5 9.5a1.25 1.25 0 110 2.5 1.25 1.25 0 010-2.5zM8.5 9.5a1.25 1.25 0 110 2.5 1.25 1.25 0 010-2.5zM12 2C6.47 2 2 6.48 2 12s4.47 10 10 10 10-4.48 10-10S17.53 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8z" />
  </svg>
);

// The parent notes written about the student: the total, then how many are positive (praise), neutral and negative (to improve),
// each with its own icon, colour and word, so nothing has to be decoded from symbols.
const NoteKinds = ({ feedback }) => {
  const kinds = [
    { key: 'positive', label: 'Positive', color: TONE_COLORS.good, Icon: SentimentSatisfiedAltIcon },
    { key: 'neutral', label: 'Neutral', color: '#757575', Icon: NeutralFaceIcon },
    { key: 'negative', label: 'Negative', color: TONE_COLORS.bad, Icon: SentimentDissatisfiedIcon },
  ];
  return (
    <div style={{ marginTop: 12 }}>
      <div style={{ fontSize: 11, color: '#6b778a', fontWeight: 'bold', textTransform: 'uppercase', marginBottom: 4 }}>
        Parent notes · {feedback?.total ?? 0}
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {kinds.map(({ key, label, color, Icon }) => (
          <div
            key={key}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 6,
              padding: '3px 12px',
              borderRadius: 16,
              border: `1px solid ${color}40`,
              background: `${color}12`,
              color,
            }}>
            <Icon style={{ fontSize: 18 }} />
            <b style={{ fontSize: 14 }}>{feedback?.[key] ?? 0}</b>
            <span style={{ fontSize: 12, color: '#555' }}>{label}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

const percentText = value => `${Math.round((Number(value) || 0) * 10) / 10}%`;

// The student's progress at a glance on the Basic Info tab: attendance, home work, exam average, parent notes and appreciation
// cards, from the one dashboard progress API. Read again whenever the student changes.
const StudentProgressPanel = ({ studentId, token, profile }) => {
  const [progress, setProgress] = useState(null);
  const [addresses, setAddresses] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!studentId) return undefined;
    let cancelled = false;
    setProgress(null);
    setError('');
    setLoading(true);
    const { batchId } = getGlobalCurrentBatchUtils() || {};
    setAddresses(null);
    fetchStudentContactsApi({ studentId, token })
      .then(list => !cancelled && setAddresses(list))
      .catch(() => !cancelled && setAddresses([]));
    fetchStudentProgressApi({ studentId, batchId, token })
      .then(data => !cancelled && setProgress(data))
      .catch(() => !cancelled && setError('Could not load the progress'))
      .finally(() => !cancelled && setLoading(false));
    return () => {
      cancelled = true;
    };
  }, [studentId, token]);

  if (error) {
    return <p style={{ color: '#c62828', marginBottom: 12 }}>{error}</p>;
  }
  const { attendance, homework, performance, feedback, recognition } = progress || {};
  const completion = addresses ? computeStudentCompletion(profile, addresses) : null;
  const noMarks = !loading && !performance?.examsCompleted;
  // nothing recorded yet is shown as "--", not as a red 0%
  const noAttendance = !loading && !attendance?.totalDays;
  const noHomework = !loading && !homework?.total;

  return (
    <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0', marginBottom: 16 }}>
      <b>Progress</b>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10, marginTop: 12 }}>
        <StatTile
          label="Profile completion"
          loading={loading || !completion}
          value={completion ? `${completion.percent}%` : '--'}
          tone={completion ? toneFor(completion.percent) : 'neutral'}
          note={completion ? `${completion.filled}/${completion.total} details filled` : undefined}
        />
        <StatTile
          label="Attendance"
          loading={loading}
          value={noAttendance ? '--' : percentText(attendance?.attendancePercent)}
          tone={noAttendance ? 'neutral' : toneFor(attendance?.attendancePercent)}
          note={attendance ? `${attendance.presentDays}/${attendance.totalDays} days present` : undefined}
        />
        <StatTile
          label="Home work done"
          loading={loading}
          value={noHomework ? '--' : percentText(homework?.completionPercent)}
          tone={noHomework ? 'neutral' : toneFor(homework?.completionPercent)}
          note={homework ? `${homework.pending} pending · ${homework.overdue} overdue` : undefined}
        />
        <StatTile
          label="Exam average"
          loading={loading}
          value={noMarks ? '--' : percentText(performance?.averagePercent)}
          tone={noMarks ? 'neutral' : toneFor(performance?.averagePercent)}
          note={performance ? (noMarks ? 'No marks yet' : `${performance.examsCompleted} exams`) : undefined}
        />
        <StatTile
          label="Appreciation cards"
          loading={loading}
          value={recognition?.totalAppreciationCards ?? 0}
          tone="info"
        />
      </div>
      {!loading && <NoteKinds feedback={feedback} />}
      {!!completion?.missing?.length && (
        <div style={{ marginTop: 14 }}>
          <div
            style={{ fontSize: 11, color: '#6b778a', fontWeight: 'bold', textTransform: 'uppercase', marginBottom: 4 }}>
            Still missing
          </div>
          <div style={{ color: '#555' }}>{completion.missing.join(', ')}</div>
        </div>
      )}
      {!loading && !!feedback?.improvementAreas?.length && (
        <div style={{ marginTop: 14 }}>
          <div
            style={{ fontSize: 11, color: '#6b778a', fontWeight: 'bold', textTransform: 'uppercase', marginBottom: 4 }}>
            Needs attention
          </div>
          <ul style={{ margin: 0, paddingLeft: 18, color: '#555' }}>
            {feedback.improvementAreas.map(text => (
              <li key={text}>{text}</li>
            ))}
          </ul>
        </div>
      )}
    </Paper>
  );
};

export default StudentProgressPanel;
