import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label } from 'reactstrap';
import CustomInput from 'views/admin/Common/CustomInput';
import Select from 'react-select';
import CustomButton from 'components/CustomButton';
import { selectStyle } from 'views/admin/Reports';
import { formResMessage } from 'utils/commonFunc';
import colors from 'config/colors';
import { PAYMENT_MODES } from 'config/constants';

// Same modes as everywhere else, but this backend field is plain text, so the label itself is what gets stored.
const paymentModeOptions = PAYMENT_MODES.map(mode => ({ label: mode.label, value: mode.label }));

const initialState = {
  adjustFeeId: 0,
  amount: 0,
  currCourseId: 0,
  feeStructId: 0,
  paidStatus: 'FULLY_PAID',
  paymentMode: '',
  paymentNotes: '',
  schoolId: 0,
  studPaymentId: 0,
  studentId: 0,
  transactionId: '',
};

const validateForm = data => {
  const errors = {};
  if (!data?.feeStructId) {
    errors['feeStructId'] = 'Fee cannot be empty';
  }
  if (!data?.paidStatus) {
    errors['paidStatus'] = 'Paid status cannot be empty';
  }
  if (!data?.paymentMode) {
    errors['paymentMode'] = 'Payment mode cannot be empty';
  }
  if (!data?.amount) {
    errors['amount'] = 'Amount cannot be empty';
  }
  if (!data?.transactionId) {
    errors['transactionId'] = 'Transaction Id cannot be empty';
  }
  return errors;
};

// Each fee-structure line's payable amount, same computation StudentFeesPanel's Fee Structure
// table uses (expectedAmount when set, else actualAmount - discountAmount).
const feeAmount = item => Number(item?.expectedAmount ?? (item?.actualAmount || 0) - (item?.discountAmount || 0));

const buildFeeNotes = items => (items.length ? `Payment for: ${items.map(el => el.feeDescription).join(', ')}` : '');

// The backend only accepts ONE feeStructId per payment (StudentPaymentHistory.feeStructId is a
// single Long, not a list) - selecting several terms below still submits a single payment row
// against the FIRST selected term, with the cumulative amount and an auto-built comment listing
// every term actually being paid for, so the full detail survives even though only one
// feeStructId is recorded. No backend change.
const PaymentForm = ({
  isShow,
  courseId,
  studentId,
  studentFeesStructures,
  hideForm,
  payStudentFeePayment,
  updateSuccess,
}) => {
  const [loading, setLoading] = useState(false);
  const [state, setState] = useState(initialState);
  const [errors, setError] = useState({});
  const [globalError, setGlobalError] = useState('');
  const [selectedFeeStructIds, setSelectedFeeStructIds] = useState([]);
  const [amountTouched, setAmountTouched] = useState(false);
  const [notesTouched, setNotesTouched] = useState(false);

  useEffect(() => {
    if (isShow) {
      setState(initialState);
      setError({});
      setGlobalError('');
      setLoading(false);
      setSelectedFeeStructIds([]);
      setAmountTouched(false);
      setNotesTouched(false);
    }
  }, [isShow]);

  const cancelPayment = () => {
    setState(initialState);
    setLoading(false);
    setSelectedFeeStructIds([]);
    setAmountTouched(false);
    setNotesTouched(false);
    hideForm();
  };

  const handleChange = (name, value) => {
    if (name === 'amount') setAmountTouched(true);
    if (name === 'paymentNotes') setNotesTouched(true);
    setState(prevState => ({
      ...prevState,
      [name]: value,
    }));
  };

  const applyFeeStructIds = nextIds => {
    setSelectedFeeStructIds(nextIds);
    const selectedItems = (studentFeesStructures || []).filter(el => nextIds.includes(el.feeStructId));
    setState(prevState => ({
      ...prevState,
      feeStructId: nextIds[0] || 0,
      amount: amountTouched ? prevState.amount : selectedItems.reduce((sum, el) => sum + feeAmount(el), 0),
      paymentNotes: notesTouched ? prevState.paymentNotes : buildFeeNotes(selectedItems),
    }));
    setError(prevErrors => ({ ...prevErrors, feeStructId: undefined }));
  };

  // Amount/notes stay auto-computed from the selection until the admin edits them directly -
  // once touched, further term toggles no longer overwrite that manual value.
  const toggleFeeStructure = feeStructId => {
    applyFeeStructIds(
      selectedFeeStructIds.includes(feeStructId)
        ? selectedFeeStructIds.filter(id => id !== feeStructId)
        : [...selectedFeeStructIds, feeStructId]
    );
  };

  const selectAllFeeStructures = () => applyFeeStructIds((studentFeesStructures || []).map(el => el.feeStructId));
  const clearAllFeeStructures = () => applyFeeStructIds([]);

  const handleSubmit = async e => {
    e.preventDefault();
    const error = validateForm(state);
    setError(error);
    if (!Object.keys(error)?.length) {
      setLoading(true);
      try {
        await payStudentFeePayment({ ...state, currCourseId: courseId, courseId, studentId });
        setLoading(false);
        setGlobalError('');
        updateSuccess();
      } catch (err) {
        setLoading(false);
        setGlobalError(formResMessage(err));
      }
    }
  };

  const paidStatus = [
    { label: 'Fully paid', value: 'FULLY_PAID' },
    { label: 'Partially paid', value: 'PARTIALLY_PAID' },
  ];

  const selectedItems = (studentFeesStructures || []).filter(el => selectedFeeStructIds.includes(el.feeStructId));
  const allFeesSelected =
    !!studentFeesStructures?.length && selectedFeeStructIds.length === studentFeesStructures.length;

  return (
    <Modal size="lg" scrollable centered isOpen={isShow} className="modal-offset-sidebar">
      <ModalHeader toggle={cancelPayment}>
        <span style={{ fontSize: 18, whiteSpace: 'nowrap' }}>Add Payment</span>
      </ModalHeader>
      <form onSubmit={handleSubmit}>
        <ModalBody>
          {globalError && <div className="err-msg mb-2">{globalError}</div>}
          <Row>
            <Col md={12}>
              <div className="mb-3">
                <div
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'baseline',
                    flexWrap: 'wrap',
                  }}>
                  <Label style={{ marginBottom: 4 }}>
                    Fee / Term
                    <sup> *</sup>{' '}
                    <span style={{ fontWeight: 400, color: '#5e6977', fontSize: 13 }}>(select one or more)</span>
                  </Label>
                  {!!studentFeesStructures?.length && (
                    <span
                      onClick={allFeesSelected ? clearAllFeeStructures : selectAllFeeStructures}
                      style={{ color: colors.accent, fontSize: 13, fontWeight: 'bold', cursor: 'pointer' }}>
                      {allFeesSelected ? 'Clear all' : 'Select all'}
                    </span>
                  )}
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, maxHeight: 260, overflowY: 'auto' }}>
                  {(studentFeesStructures || []).map(item => {
                    const selected = selectedFeeStructIds.includes(item.feeStructId);
                    return (
                      <div
                        key={item.feeStructId}
                        onClick={() => toggleFeeStructure(item.feeStructId)}
                        style={{
                          cursor: 'pointer',
                          userSelect: 'none',
                          minWidth: 120,
                          padding: '8px 12px',
                          borderRadius: 8,
                          border: `2px solid ${selected ? colors.accent : '#e0e0e0'}`,
                          backgroundColor: selected ? `${colors.accent}14` : '#fff',
                        }}>
                        <div style={{ fontWeight: 'bold', fontSize: 13 }}>{item.feeDescription}</div>
                        <div style={{ fontSize: 12, color: '#6b778a' }}>₹{feeAmount(item)}</div>
                      </div>
                    );
                  })}
                  {!studentFeesStructures?.length && (
                    <span style={{ color: '#9a9a9a', fontSize: 13 }}>No fee structure assigned.</span>
                  )}
                </div>
                {errors.feeStructId && <span className="err-msg">{errors.feeStructId}</span>}
                {!!selectedItems.length && (
                  <div style={{ fontSize: 12, color: '#6b778a', marginTop: 6 }}>
                    Selected: {selectedItems.map(el => el.feeDescription).join(', ')} ({selectedItems.length} fee
                    {selectedItems.length > 1 ? 's' : ''}) &middot; Suggested total: ₹
                    {selectedItems.reduce((sum, el) => sum + feeAmount(el), 0)}
                  </div>
                )}
              </div>
            </Col>
            <Col md={6}>
              <CustomInput
                label={
                  <>
                    Amount<sup> *</sup>
                  </>
                }
                name="amount"
                value={state.amount}
                onChange={handleChange}
                error={errors.amount}
              />
            </Col>
            <Col md={6}>
              <div className="mb-3">
                <Label>
                  Paid status<sup> *</sup>
                </Label>
                <Select
                  name="paidStatus"
                  options={paidStatus}
                  value={paidStatus.find(el => el.value === state.paidStatus) || null}
                  onChange={dto => handleChange('paidStatus', dto.value)}
                  styles={selectStyle(!errors.paidStatus)}
                />
                {errors.paidStatus && <span className="err-msg">{errors.paidStatus}</span>}
              </div>
            </Col>
            <Col md={6}>
              <div className="mb-3">
                <Label>
                  Payment mode<sup> *</sup>
                </Label>
                <Select
                  name="paymentMode"
                  options={paymentModeOptions}
                  value={paymentModeOptions.find(el => el.value === state.paymentMode) || null}
                  onChange={dto => handleChange('paymentMode', dto.value)}
                  styles={selectStyle(!errors.paymentMode)}
                />
                {errors.paymentMode && <span className="err-msg">{errors.paymentMode}</span>}
              </div>
            </Col>
            <Col md={6}>
              <CustomInput
                label={
                  <>
                    Transaction Id<sup> *</sup>
                  </>
                }
                name="transactionId"
                value={state.transactionId}
                onChange={handleChange}
                error={errors?.transactionId}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                label="Payment Notes"
                name="paymentNotes"
                type="textarea"
                placeholder="Optional notes about this payment..."
                value={state.paymentNotes}
                onChange={handleChange}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={cancelPayment}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Pay now"
            disabled={loading}
            loading={loading}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default PaymentForm;
