import React from 'react';
import { isFlaggedStudentStatus, studentStatusColor, studentStatusLabel } from 'utils/studentStatus';

// The label of a student with a non-active status (Transfer Certificate Issued, Dropped Out ...); nothing for an ordinary student.
const StudentStatusTag = ({ status, style }) => {
  if (!isFlaggedStudentStatus(status)) return null;
  const color = studentStatusColor(status);
  return (
    <span
      style={{
        display: 'inline-block',
        padding: '3px 9px',
        borderRadius: 5,
        fontSize: 11,
        fontWeight: 'bold',
        whiteSpace: 'nowrap',
        color: '#fff',
        background: color,
        ...style,
      }}>
      {studentStatusLabel(status)}
    </span>
  );
};

export default StudentStatusTag;
