import React, { useEffect, useState } from 'react';
import moment from 'moment';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label } from 'reactstrap';
import Select from 'react-select';
import { Radio } from '@material-ui/core';
import CustomButton from 'components/CustomButton';
import CustomInput from 'views/admin/Common/CustomInput';
import { formResMessage } from 'utils/commonFunc';
import { selectStyle } from 'views/admin/Reports';
import colors from 'config/colors';

const emptyForm = {
  studentCustomBillId: 0,
  studentId: null,
  billName: '',
  description: '',
  amount: '',
  dueDate: '',
  payerType: 'STUDENT', // NEW: 'STUDENT' | 'OTHER'
  payerName: '', // NEW
  payerPhone: '', // NEW
};

// Who pays. Same two cards as the Unofficial bills form: a school student, or someone from outside (a parent, visitor, donor).
const PAYER_TYPES = [
  {
    key: 'STUDENT',
    label: 'School student',
    icon: 'fas fa-user-graduate',
    description: 'Pick a student of the current academic year.',
  },
  {
    key: 'OTHER',
    label: 'Other person',
    icon: 'fas fa-user-edit',
    description: 'Type the name and mobile, e.g. a parent, visitor or donor.',
  },
];

const todayIso = () => new Date().toISOString().slice(0, 10);

const BillingFormModal = ({
  isOpen,
  onClose,
  editingBill,
  isSaving = false,
  onCreate,
  onUpdate,
  showWarning,
  showStudentPicker = false,
  studentOptions = [],
  isStudentsLoading = false,
}) => {
  const [form, setForm] = useState(emptyForm);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setForm(
        editingBill
          ? {
              studentCustomBillId: editingBill.studentCustomBillId,
              studentId: editingBill.studentId,
              billName: editingBill.billName,
              description: editingBill.description || '',
              amount: editingBill.amount,
              dueDate: editingBill.dueDate || '',
              // NEW: an existing bill without a studentId belongs to an outside person
              payerType: editingBill.studentId ? 'STUDENT' : 'OTHER',
              payerName: editingBill.studentId ? '' : editingBill.payerName || '',
              payerPhone: editingBill.studentId ? '' : editingBill.payerPhone || '',
              schoolId: editingBill.schoolId,
              batchId: editingBill.batchId,
              billDate: editingBill.billDate,
              billType: editingBill.billType,
              referenceType: editingBill.referenceType,
              referenceId: editingBill.referenceId,
            }
          : emptyForm
      );
      setErrors({});
    }
  }, [isOpen, editingBill]);

  const handleChange = (name, value) => setForm(prev => ({ ...prev, [name]: value }));

  // NEW: switch between school student / other person
  const handlePayerType = payerType => {
    setForm(prev => ({
      ...prev,
      payerType,
      studentId: payerType === 'OTHER' ? null : prev.studentId,
    }));
    setErrors({});
  };

  const isOther = showStudentPicker && form.payerType === 'OTHER'; // NEW

  const minDueDate = form.billDate || todayIso();

  const validate = () => {
    const err = {};
    if (showStudentPicker && !isOther && !form.studentId) err.studentId = 'Select a student';
    if (isOther) {
      if (!form.payerName?.trim()) err.payerName = 'Enter the payer name';
      if (form.payerPhone && form.payerPhone.length !== 10) err.payerPhone = 'Enter a valid 10 digit mobile number';
    }
    if (!form.billName?.trim()) err.billName = 'Enter a bill name';
    if (!form.amount || Number(form.amount) <= 0) err.amount = 'Enter a valid amount';
    if (form.dueDate && form.dueDate < minDueDate) err.dueDate = 'Due date cannot be before the bill was created';
    setErrors(err);
    return !Object.keys(err).length;
  };

  const handleSubmit = e => {
    e.preventDefault();
    if (!validate()) return;
    const isUpdate = !!form.studentCustomBillId;
    const postData = {
      // CHANGED: for an outside person studentId is sent as null (update) or omitted (create)
      ...(isOther
        ? isUpdate
          ? { studentId: null }
          : {}
        : showStudentPicker || isUpdate
        ? { studentId: form.studentId }
        : {}),
      // NEW: payer details for an outside person
      ...(isOther ? { payerName: form.payerName.trim(), payerPhone: form.payerPhone || null } : {}),
      ...(isUpdate
        ? {
            schoolId: form.schoolId,
            batchId: form.batchId,
            billDate: form.billDate,
            referenceType: form.referenceType,
            referenceId: form.referenceId,
          }
        : {}),
      billType: isUpdate ? form.billType : 'CUSTOM',
      ...(isUpdate ? {} : { billDate: moment().format('YYYY-MM-DDTHH:mm:ss') }),
      billName: form.billName.trim(),
      description: form.description?.trim() || null,
      amount: Number(form.amount),
      dueDate: form.dueDate || null,
    };
    const promise = isUpdate ? onUpdate(form.studentCustomBillId, postData) : onCreate(postData);
    promise.then(() => onClose()).catch(err => showWarning?.(formResMessage(err), 'error'));
  };

  return (
    <Modal size="lg" scrollable centered isOpen={isOpen} className="modal-offset-sidebar">
      <ModalHeader toggle={onClose}>{form.studentCustomBillId ? 'Update Bill' : 'Add Bill'}</ModalHeader>
      <form onSubmit={handleSubmit}>
        <ModalBody>
          <Row>
            {showStudentPicker && (
              <>
                <Col md={12}>
                  <Label>
                    Payer<sup> *</sup>
                  </Label>
                  <Row className="mb-2">
                    {PAYER_TYPES.map(item => {
                      const checked = form.payerType === item.key;
                      return (
                        <Col key={item.key} sm={6} className="mb-2">
                          <div
                            role="radio"
                            aria-checked={checked}
                            tabIndex={0}
                            onClick={() => handlePayerType(item.key)}
                            onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && handlePayerType(item.key)}
                            style={{
                              display: 'flex',
                              alignItems: 'center',
                              gap: 4,
                              height: '100%',
                              padding: '10px 12px',
                              borderRadius: 8,
                              border: `1.5px solid ${checked ? colors.accent : '#e0e0e0'}`,
                              backgroundColor: checked ? '#F5EDFB' : '#fff',
                              cursor: 'pointer',
                            }}>
                            <Radio checked={checked} size="small" style={{ color: colors.accent, padding: 2 }} />
                            <div>
                              <div style={{ fontWeight: 'bold', fontSize: 13 }}>
                                <i className={item.icon} style={{ marginRight: 6, color: colors.accent }} />
                                {item.label.toUpperCase()}
                              </div>
                              <div style={{ fontSize: 12, color: '#6b778a', marginTop: 2 }}>{item.description}</div>
                            </div>
                          </div>
                        </Col>
                      );
                    })}
                  </Row>
                </Col>

                {!isOther ? (
                  <Col md={12}>
                    <div className="mb-3">
                      <Label>
                        Student<sup> *</sup>
                      </Label>
                      <Select
                        name="studentId"
                        options={studentOptions}
                        value={studentOptions.find(el => el.value === form.studentId) || null}
                        onChange={dto => handleChange('studentId', dto.value)}
                        placeholder="Search & select student..."
                        isSearchable
                        isLoading={isStudentsLoading}
                        noOptionsMessage={() => (isStudentsLoading ? 'Loading students...' : 'No students found')}
                        styles={selectStyle(!errors.studentId)}
                      />
                      {errors.studentId && <span className="err-msg">{errors.studentId}</span>}
                    </div>
                  </Col>
                ) : (
                  <>
                    {/* NEW: outside person details */}
                    <Col md={6}>
                      <CustomInput
                        label={
                          <>
                            Name<sup> *</sup>
                          </>
                        }
                        name="payerName"
                        placeholder="Enter name"
                        value={form.payerName}
                        onChange={handleChange}
                        error={errors.payerName}
                      />
                    </Col>
                    <Col md={6}>
                      <CustomInput
                        label="Mobile number"
                        name="payerPhone"
                        placeholder="10 digit mobile number"
                        value={form.payerPhone}
                        onChange={(name, value) => handleChange(name, String(value).replace(/\D/g, '').slice(0, 10))}
                        error={errors.payerPhone}
                      />
                    </Col>
                  </>
                )}
              </>
            )}
            <Col md={12}>
              <CustomInput
                label={
                  <>
                    Bill name<sup> *</sup>
                  </>
                }
                name="billName"
                placeholder="e.g. Lost ID card fee, Late fee"
                value={form.billName}
                onChange={handleChange}
                error={errors.billName}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                type="number"
                label={
                  <>
                    Amount<sup> *</sup>
                  </>
                }
                name="amount"
                placeholder="Enter amount"
                value={form.amount}
                onChange={handleChange}
                error={errors.amount}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                type="textarea"
                rows={3}
                label="Notes (optional)"
                name="description"
                placeholder="Any extra detail"
                value={form.description}
                onChange={handleChange}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                type="date"
                label="Due date (optional)"
                name="dueDate"
                value={form.dueDate}
                onChange={handleChange}
                error={errors.dueDate}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={isSaving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            loading={isSaving}
            disabled={isSaving}
            name={form.studentCustomBillId ? 'Update' : 'Save'}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default BillingFormModal;
