import React, { useState, useEffect, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Paper } from '@material-ui/core';
import { Row, Col } from 'reactstrap';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import moment from 'moment';
import colors from 'config/colors';
import { CommonLoader } from 'views/admin/Common/Loader';
import CustomButton from 'components/CustomButton';
import { getGlobalSchoolUtils, getGlobalCurrentBatchUtils, formatMoney } from 'utils/commonFunc';
import { showToast } from 'actions/admin/auth';
import {
  fetchStudentBillingsService,
  addStudentBillingService,
  updateStudentBillingService,
} from 'actions/admin/billing';
import BillingFormModal from './BillingFormModal';
import BillTypeTag from './BillTypeTag';
import BillReceiptLinks from 'views/admin/Common/BillReceiptLinks';
import EmptyState from 'views/admin/Common/EmptyState';

// Bills sub-tab of the student's Fees & Bills tab. Unofficial bills aren't shown here - they have
// their own admin-only page (views/admin/UnofficialBills), since they can be for anyone, not just a student.
const StudentBillsPanel = ({ studentId, loggedUserSchool, loggedUserToken }) => {
  const dispatch = useDispatch();
  const [isFetching, setIsFetching] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const bills = useSelector(state => state.billing?.billingsByStudent?.[studentId]);

  const getSchoolId = () => loggedUserSchool || getGlobalSchoolUtils()?.schoolId;
  const showWarning = (msg, type) => dispatch(showToast(msg, type));

  const fetchBillings = useCallback(() => {
    if (!studentId) return Promise.resolve();
    setIsFetching(true);
    return dispatch(
      fetchStudentBillingsService({
        schoolId: loggedUserSchool || getGlobalSchoolUtils()?.schoolId,
        studentId,
        token: loggedUserToken,
      })
    ).then(() => setIsFetching(false));
  }, [dispatch, studentId, loggedUserSchool, loggedUserToken]);

  useEffect(() => {
    fetchBillings();
  }, [fetchBillings]);

  const submitCreateBill = postData => {
    const { batchId } = getGlobalCurrentBatchUtils();
    setIsSaving(true);
    return dispatch(
      addStudentBillingService({
        ...postData,
        studentId,
        schoolId: getSchoolId(),
        batchId,
        token: loggedUserToken,
      })
    )
      .then(() => {
        setIsSaving(false);
        fetchBillings();
      })
      .catch(err => {
        setIsSaving(false);
        throw err;
      });
  };

  const submitUpdateBill = (studentCustomBillId, postData) => {
    setIsSaving(true);
    return dispatch(updateStudentBillingService({ ...postData, studentCustomBillId, token: loggedUserToken }))
      .then(() => {
        setIsSaving(false);
        fetchBillings();
      })
      .catch(err => {
        setIsSaving(false);
        throw err;
      });
  };

  return (
    <>
      <Row>
        <Col>
          <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
            <div className="card-category font-weight-bold mb-3" style={{ overflow: 'hidden' }}>
              Bills{' '}
              <div style={{ float: 'right' }}>
                <CustomButton
                  size="small"
                  name="+ Add Bill"
                  onClick={() => setIsModalOpen(true)}
                  style={{ backgroundColor: colors.accent, color: colors.white }}
                />
              </div>
            </div>
            <div style={{ overflowX: 'auto' }}>
              <Table size="small" aria-label="a dense table">
                <TableHead>
                  <TableRow style={{ backgroundColor: '#e0e0e0' }}>
                    <TableCell component="th">
                      <b>Bill Name</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Type</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Notes</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Amount</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Bill Date</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Due Date</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Receipt</b>
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {isFetching ? (
                    <TableRow>
                      <TableCell colSpan={7} component="td">
                        <div style={{ textAlign: 'center' }}>
                          <CommonLoader />
                        </div>
                      </TableCell>
                    </TableRow>
                  ) : bills?.length ? (
                    bills.map(item => (
                      <TableRow key={item.studentCustomBillId}>
                        <TableCell component="th" scope="row">
                          {item.billName}
                        </TableCell>
                        <TableCell align="left">
                          <BillTypeTag billType={item.billType} />
                        </TableCell>
                        <TableCell align="left">{item.description || '--'}</TableCell>
                        <TableCell align="left">{formatMoney(item.amount)}</TableCell>
                        <TableCell align="left">
                          {item.billDate ? moment(item.billDate).format('DD MMM, YYYY hh:mm A') : '--'}
                        </TableCell>
                        <TableCell align="left">
                          {item.dueDate ? moment(item.dueDate).format('DD MMM, YYYY hh:mm A') : '--'}
                        </TableCell>
                        <TableCell align="left">
                          <BillReceiptLinks
                            billId={item.studentCustomBillId}
                            status={item.status}
                            schoolId={getSchoolId()}
                          />
                        </TableCell>
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell colSpan={7} component="td">
                        <EmptyState
                          compact
                          bare
                          icon="fas fa-file-invoice"
                          title="No bills added for this student yet"
                        />
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
          </Paper>
        </Col>
      </Row>
      <BillingFormModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        editingBill={null}
        isSaving={isSaving}
        onCreate={submitCreateBill}
        onUpdate={submitUpdateBill}
        showWarning={showWarning}
      />
    </>
  );
};

export default StudentBillsPanel;
