import React from 'react';
import { connect } from 'react-redux';
import { store } from 'index';
import { fetchStudentFullInfoService, clearStudentFullInfo, payStudentFeePaymentService } from 'actions/admin/students';
import { fetchReportService } from 'actions/admin/reports';
import {
  createStudentFeeRefundService,
  fetchRefundsForPaymentService,
  fetchRefundTotalForPaymentService,
  fetchRefundsForStudentBatchService,
} from 'actions/admin/fees';
import { getGlobalSchoolUtils, getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import StudentDetailView from './components/StudentDetailView.jsx';

class StudentViewPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: null,
      profileFetching: false,
      activitiesFetching: false,
      homeworkFetching: false,
      assignmentsFetching: false,
      feeStructureFetching: false,
      paymentsFetching: false,
    };
  }

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    this.setState({ schoolId: globalSchool?.schoolId });
    store.dispatch(clearStudentFullInfo());
    this.fetchStudentFullInfo('profile', { studentId: this.getStudentId() });
  }

  getStudentId = () => Number(this.props.match?.params?.studentId);

  isLoading = (name, value) => this.setState({ [name]: value });

  fetchStudentFullInfo = async (type, paramsData) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const globalSchool = getGlobalSchoolUtils();
    paramsData['schoolId'] = this.state.schoolId || globalSchool.schoolId;
    this.isLoading(`${type}Fetching`, true);
    await this.props.fetchStudentFullInfo({ type, ...paramsData, token: this.props.loggedUserToken, batchId });
    this.isLoading(`${type}Fetching`, false);
  };

  fetchInfo = (type, paramsData) => this.fetchStudentFullInfo(type, paramsData);

  payStudentFeePayment = data => {
    const globalSchool = getGlobalSchoolUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    return this.props.payStudentFeePayment({
      ...data,
      schoolId: this.state.schoolId || globalSchool.schoolId,
      batchId,
      token: this.props.loggedUserToken,
    });
  };

  updatePaymentSuccess = data => this.fetchInfo('payments', data);

  // Back to the tabbed Students/Guardians page - plain /admin/students renders the list on its own,
  // without the main tabs.
  goBack = () => this.props.history.push('/admin/school-students?school-students');

  render() {
    return (
      <StudentDetailView
        history={this.props.history}
        location={this.props.location}
        onBack={this.goBack}
        fetchInfo={this.fetchInfo}
        payStudentFeePayment={this.payStudentFeePayment}
        updateSuccess={this.updatePaymentSuccess}
        fetchandShowFeesReceiptReport={this.props.fetchandShowFeesReceiptReport}
        createRefund={this.props.createRefund}
        refundsByStudent={this.props.refundsByStudent}
        fetchRefundsForStudentBatch={this.props.fetchRefundsForStudentBatch}
        refundsByPayment={this.props.refundsByPayment}
        refundTotalByPayment={this.props.refundTotalByPayment}
        fetchRefundsForPayment={this.props.fetchRefundsForPayment}
        fetchRefundTotalForPayment={this.props.fetchRefundTotalForPayment}
        loggedUserSchool={this.props.loggedUserSchool}
        loggedUserToken={this.props.loggedUserToken}
        {...this.state}
        studentReducer={{
          lastFetch: this.props.lastFetch,
          profile: this.props.profile,
          homework: this.props.homework,
          assignments: this.props.assignments,
          feeStructure: this.props.feeStructure,
          payments: this.props.payments,
          activities: this.props.activities,
        }}
      />
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserSchool: state.auth.loggedUserSchool,
    lastFetch: state.students.lastFetch,
    profile: state.students.profile,
    homework: state.students.homework,
    assignments: state.students.assignments,
    feeStructure: state.students.feeStructure,
    payments: state.students.payments,
    activities: state.students.activities,
    refundsByStudent: state.fees?.refundsByStudent,
    refundsByPayment: state.fees?.refundsByPayment,
    refundTotalByPayment: state.fees?.refundTotalByPayment,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchStudentFullInfo: data => dispatch(fetchStudentFullInfoService(data)),
    payStudentFeePayment: data => dispatch(payStudentFeePaymentService(data)),
    fetchandShowFeesReceiptReport: data => dispatch(fetchReportService(data)),
    createRefund: data => dispatch(createStudentFeeRefundService(data)),
    fetchRefundsForPayment: data => dispatch(fetchRefundsForPaymentService(data)),
    fetchRefundTotalForPayment: data => dispatch(fetchRefundTotalForPaymentService(data)),
    fetchRefundsForStudentBatch: data => dispatch(fetchRefundsForStudentBatchService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(StudentViewPage);
