import React, { useState } from 'react';
import { Card, CardBody, FormGroup, Form, Input, Row, Col } from 'reactstrap';
// Material UI
import moment from 'moment';
import Validator from 'validator';
import FormControlLabel from '@material-ui/core/FormControlLabel';
import Checkbox from '@material-ui/core/Checkbox';
import { showToast } from '../../../actions/admin/auth';
import { store } from '../../..';
import CustomButton from '../../../components/CustomButton';
import { formResMessage } from 'utils/commonFunc';

moment.suppressDeprecationWarnings = true;

const ChangePassword = ({ email, updatePassword }) => {
  const stateObj = {
    data: {
      oldPassword: '',
      newPassword: '',
      confirmPassword: '',
    },
    errors: {},
    loading: false,
  };

  const [canUpdatePassword, handleTogglePasswordChange] = useState(false);
  const [stateVal, setState] = useState(stateObj);
  const [showPassword, togglePasswordShow] = useState(false);

  const handleChange = (name, value) => {
    setState(prevState => {
      return {
        ...prevState,
        data: {
          ...prevState.data,
          [name]: value,
        },
      };
    });
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data } = stateVal;
    const errors = validate(data);
    setState({ ...stateVal, errors });
    if (!Object.keys(errors).length) {
      setState({ ...stateVal, errors: {}, loading: true });
      return updatePassword(data)
        .then(() => {
          store.dispatch(
            showToast(`Your request sent successfully, Your password will get update within an hour`, 'success')
          );
          resetForm();
        })
        .catch(err => {
          setError(err);
        });
    }
  };

  const validate = data => {
    const errors = {};
    if (Validator.isEmpty(data.oldPassword)) {
      errors.oldPassword = 'Old password cannot be empty';
    }
    if (Validator.isEmpty(data.confirmPassword)) {
      errors.confirmPassword = 'Confirm password cannot be empty';
    }
    if (Validator.isEmpty(data.newPassword)) {
      errors.newPassword = 'New password cannot be empty';
    } else if (!Validator.matches(data.newPassword, /^(?=.*[0-9])(?=.*[!@#$%^&*])[a-zA-Z0-9!@#$%^&*]{6,16}$/)) {
      errors.newPassword =
        'The password should contain atleast six characters length, one number and one special character';
    }
    if (data.confirmPassword && data.newPassword !== data.confirmPassword) {
      errors.confirmPassword = 'Password is mismatch';
    }
    return errors;
  };

  const resetForm = () => {
    setState(stateObj);
    handleTogglePasswordChange(!canUpdatePassword);
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const { data, loading, errors } = stateVal;
  let type = 'password';
  if (showPassword) {
    type = 'text';
  } else {
    type = 'password';
  }

  return (
    <Card className="card-user">
      <CardBody>
        {canUpdatePassword ? (
          <>
            {email.includes('demo') && (
              <>
                <span style={{ color: 'orange' }}>Note: Demo user can&apos;t change password</span>
                <br />
              </>
            )}
            <FormControlLabel
              control={<Checkbox checked={!!showPassword} onChange={() => togglePasswordShow(!showPassword)} />}
              label="Show password"
            />
            <Form>
              {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
              <Row>
                <Col md="12">
                  <FormGroup>
                    <label>
                      Old password <sup>*</sup>
                    </label>
                    <Input
                      type={type}
                      value={data?.oldPassword}
                      onChange={e => handleChange('oldPassword', e.target.value)}
                      placeholder="Enter old password here"
                      maxLength="50"
                    />
                    {errors.oldPassword && <span className="err-msg">{errors.oldPassword}</span>}
                  </FormGroup>
                </Col>
              </Row>
              <Row>
                <Col md="12">
                  <FormGroup>
                    <label>
                      New password <sup>*</sup>
                    </label>
                    <Input
                      type={type}
                      value={data?.newPassword}
                      onChange={e => handleChange('newPassword', e.target.value)}
                      placeholder="Enter new password here"
                      maxLength="50"
                    />
                    {errors.newPassword && <span className="err-msg">{errors.newPassword}</span>}
                  </FormGroup>
                </Col>
              </Row>
              <Row>
                <Col md="12">
                  <FormGroup>
                    <label>
                      Confirm password <sup>*</sup>
                    </label>
                    <Input
                      type={type}
                      value={data?.confirmPassword}
                      onChange={e => handleChange('confirmPassword', e.target.value)}
                      placeholder="Enter confirm password here"
                      maxLength="50"
                    />
                    {errors.confirmPassword && <span className="err-msg">{errors.confirmPassword}</span>}
                  </FormGroup>
                </Col>
              </Row>
              <Row>
                <div className="update ml-auto mr-auto">
                  <CustomButton
                    className="btn-round"
                    type="submit"
                    disabled={loading || email.includes('demo')}
                    onClick={handleSubmit}
                    name="Update Password"
                    loading={loading}
                  />
                  <CustomButton
                    className="btn-round ml-2"
                    type="button"
                    color="default"
                    disabled={loading}
                    onClick={() => handleTogglePasswordChange(!canUpdatePassword)}
                    name="Cancel"
                  />
                </div>
              </Row>
            </Form>
          </>
        ) : (
          <div style={{ textAlign: 'center' }}>
            <CustomButton
              className="btn-round"
              color="primary"
              type="button"
              disabled={loading}
              onClick={() => handleTogglePasswordChange(!canUpdatePassword)}
              name="Change Password"
            />
          </div>
        )}
      </CardBody>
    </Card>
  );
};

export default ChangePassword;
