// How complete a student's profile is, from the student record and the address list the page already has (the mobile app counts
// the same 17 fields). Returns { percent, filled, total, missing: [labels] }, or null until the student is loaded.
const hasText = value => `${value ?? ''}`.trim().length > 0;

export const STUDENT_PROFILE_FIELDS = [
  ['First name', s => hasText(s.firstName)],
  ['Last name', s => hasText(s.lastName)],
  ['Date of birth', s => !!s.dateOfBirth],
  ['Gender', s => hasText(s.gender)],
  ['Blood group', s => hasText(s.bloodGroup)],
  ['Birth place', s => hasText(s.birthPlace)],
  ['Nationality', s => hasText(s.nationality)],
  ['Mother tongue', s => hasText(s.motherTongue)],
  ['Category', s => hasText(s.category)],
  ['Religion', s => hasText(s.religion)],
  ['Profile photo', s => !!s.profileImgDdbFileId],
  ['Address', (s, addresses) => (addresses || []).length > 0],
  ['Guardian name', s => hasText(s.guardName)],
  ['Guardian mobile', s => hasText(s.guardianMobile)],
  ['Guardian email', s => hasText(s.guardEmail)],
  ['Guardian occupation', s => hasText(s.guardianOccupation)],
  ['Guardian education', s => hasText(s.guardianEducation)],
];

export const computeStudentCompletion = (student, addresses) => {
  if (!student || !student.studentId) {
    return null;
  }
  const missing = STUDENT_PROFILE_FIELDS.filter(([, isFilled]) => !isFilled(student, addresses)).map(
    ([label]) => label
  );
  const total = STUDENT_PROFILE_FIELDS.length;
  const filled = total - missing.length;
  return { percent: Math.round((filled * 100) / total), filled, total, missing };
};
