import React from 'react';
import moment from 'moment';
import { formatMoney } from 'utils/commonFunc';
import SummaryCard, { Figure, Row, Progress } from './SummaryCard';

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const GREEN = '#2e7d32';
const RED = '#c62828';

// The transport fee is monthly: the fee per month, which months are paid, how much was paid in all and whether this month is
// paid. Built from the student's route (monthlyFee) and the payments listed below, whose paymentMonth is "JAN, FEB ..."
const TransportSummaryCard = ({ monthlyFee = 0, payments = [] }) => {
  const paidMonths = new Set(
    payments.flatMap(item =>
      String(item.paymentMonth || '')
        .split(',')
        .map(month => month.trim().toUpperCase())
        .filter(Boolean)
    )
  );
  const totalPaid = payments.reduce((sum, item) => sum + Number(item.amount || 0), 0);
  const thisMonth = MONTHS[moment().month()];
  const thisMonthPaid = paidMonths.has(thisMonth);
  const status = thisMonthPaid ? { label: 'This month paid', color: GREEN } : { label: 'This month due', color: RED };

  return (
    <SummaryCard title="Transport Fee Summary" status={status}>
      <Row>
        <Figure label="Fee per month" value={formatMoney(monthlyFee)} />
        <Figure label="Months paid" value={paidMonths.size} note={paidMonths.size ? undefined : 'No month paid yet'} />
        <Figure label="Total paid" value={formatMoney(totalPaid)} tone="info" />
        <Figure
          label={`${moment().format('MMMM')} fee`}
          value={thisMonthPaid ? 'Paid' : formatMoney(monthlyFee)}
          tone={thisMonthPaid ? 'good' : 'bad'}
          note={thisMonthPaid ? undefined : 'Due'}
        />
      </Row>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 12 }}>
        {MONTHS.map(month => {
          const paid = paidMonths.has(month);
          return (
            <span
              key={month}
              style={{
                minWidth: 46,
                textAlign: 'center',
                fontSize: 12,
                fontWeight: 'bold',
                padding: '4px 0',
                borderRadius: 6,
                color: paid ? GREEN : '#9a9a9a',
                background: paid ? `${GREEN}1a` : '#f5f5f5',
                border: `1px solid ${paid ? `${GREEN}55` : '#e6e6e6'}`,
              }}>
              {month}
            </span>
          );
        })}
      </div>
      <Progress
        value={paidMonths.size}
        max={MONTHS.length}
        label="Months paid this year"
        color={paidMonths.size ? GREEN : '#b0b0b0'}
      />
    </SummaryCard>
  );
};

export default TransportSummaryCard;
