import React, { useState, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { useHistory } from 'react-router-dom';
import { Paper, Tabs, Tab, CircularProgress } from '@material-ui/core';
import { Row, Col } from 'reactstrap';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import moment from 'moment';
import colors from 'config/colors';
import { CommonLoader } from 'views/admin/Common/Loader';
import { getGlobalSchoolUtils, getGlobalCurrentBatchUtils, formResMessage, formatMoney } from 'utils/commonFunc';
import CustomButton from 'components/CustomButton';
import { showToast } from 'actions/admin/auth';
import { fetchOnlinePaymentLinkApi } from 'actions/admin/students';
import { fetchStudentTransportByStudentService, fetchTransportAreaByIdService } from 'actions/admin/transportFee';
import { fetchTransportPaymentsByStudentService, createTransportPaymentService } from 'actions/admin/transportPayment';
import PaymentForm from './PaymentForm';
import PaymentRefundModal from './PaymentRefundModal';
import TransportPaymentForm from './TransportPaymentForm';
import TransportSummaryCard from './TransportSummaryCard';
import StudentBillsPanel from './StudentBillsPanel';
import AssignRouteModal from './AssignRouteModal';
import AssignFeeStructureModal from './AssignFeeStructureModal';
import FeeSummaryCard from './FeeSummaryCard';
import EmptyState from 'views/admin/Common/EmptyState';

// e.g. "FULLY_PAID" -> "Fully Paid"
const formatPaidStatus = status =>
  status
    ? status
        .toLowerCase()
        .split('_')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ')
    : '--';

// Three flat sibling sub-tabs, same pattern as StaffAttendanceHubPage - Billings moves here from
// being its own top-level student tab, since it's fee-adjacent and rarely used on its own.
const SUB_TABS = [
  { key: 'schoolFee', label: 'School Fee' },
  { key: 'transportFee', label: 'Transport Fee' },
  { key: 'refunds', label: 'Refunds' },
  { key: 'billings', label: 'Bills' },
];

// StudentFeesPanel fully unmounts whenever the outer Fees tab is switched away from (it isn't
// kept alive, see StudentDetailView's renderItems), so component state alone can't survive that -
// remember the sub-tab per student in sessionStorage instead, keyed off studentId so browsing a
// different student doesn't inherit someone else's last-viewed sub-tab.
const FEES_SUB_TAB_STORAGE_KEY = 'scholae_fees_active_sub_tab';

const getStoredSubTabIndex = studentId => {
  try {
    const storedKey = sessionStorage.getItem(`${FEES_SUB_TAB_STORAGE_KEY}_${studentId}`);
    const index = SUB_TABS.findIndex(t => t.key === storedKey);
    return index >= 0 ? index : 0;
  } catch {
    return 0;
  }
};

const storeSubTabIndex = (studentId, index) => {
  try {
    sessionStorage.setItem(`${FEES_SUB_TAB_STORAGE_KEY}_${studentId}`, SUB_TABS[index].key);
  } catch {
    // sessionStorage unavailable (e.g. private browsing) - remembering the tab is a nice-to-have,
    // not worth surfacing an error for.
  }
};

// e.g. "BANK_TRANSFER" -> "Bank Transfer"
const formatEnumLabel = value =>
  value
    ? value
        .toLowerCase()
        .split('_')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ')
    : '--';

export default function StudentFeesPanel(props) {
  const {
    studentId,
    courseId,
    loggedUserSchool,
    loggedUserToken,
    feeStructureFetching,
    paymentsFetching,
    feeStructure,
    payments,
    fetchInfo,
    payStudentFeePayment,
    updateSuccess,
    fetchandShowFeesReceiptReport,
    refundsByStudent,
    fetchRefundsForStudentBatch,
    refundsByPayment,
    refundTotalByPayment,
    fetchRefundsForPayment,
    fetchRefundTotalForPayment,
    createRefund,
  } = props;
  const dispatch = useDispatch();
  const history = useHistory();
  const globalSchool = getGlobalSchoolUtils();
  const schoolId = loggedUserSchool || globalSchool?.schoolId;
  const { batchId } = getGlobalCurrentBatchUtils();
  const [activeSubTab, setActiveSubTab] = useState(() => getStoredSubTabIndex(studentId));
  const [isAssignRouteModalOpen, setIsAssignRouteModalOpen] = useState(false);
  const [isAssignFeeStructureModalOpen, setIsAssignFeeStructureModalOpen] = useState(false);
  const [isShow, setIsShow] = useState(false);
  const [receiptFetchingId, setReceiptFetching] = useState(null);
  const [isRefundModalFetching, setIsRefundModalFetching] = useState(false);
  const [refundPayment, setRefundPayment] = useState(null);
  const [hasFetchedTransport, setHasFetchedTransport] = useState(false);
  const [transportRows, setTransportRows] = useState(null);
  const [isTransportFetching, setIsTransportFetching] = useState(false);
  const [transportPayments, setTransportPayments] = useState(null);
  const [isTransportPaymentsFetching, setIsTransportPaymentsFetching] = useState(false);
  const [isTransportPaymentFormOpen, setIsTransportPaymentFormOpen] = useState(false);
  const [transportReceiptFetchingId, setTransportReceiptFetching] = useState(null);

  // School Fee is the default sub-tab, shown as soon as the outer Fees tab opens - fetch it
  // eagerly (same as the old "fees" tab click did), the other two only once actually visited.
  useEffect(() => {
    if (!studentId) return;
    if (!feeStructure?.[studentId]?.length) {
      fetchInfo('feeStructure', { studentId, courseId });
    }
    if (!payments?.[studentId]?.length) {
      fetchInfo('payments', { studentId, courseId });
    }
    fetchRefundsForStudentBatch({ studentId, token: loggedUserToken });

    // studentId can arrive a render or two after mount (deep-linking straight to ?tab=fees, before
    // the profile fetch resolves), so the lazy useState initializer above may have read the stored
    // sub-tab against an empty studentId - re-resolve it here and, since a restored transportFee
    // sub-tab never went through changeSubTab's click handler, kick off its fetch too. (Billings
    // fetches itself when its panel mounts, so it needs nothing here.)
    const restoredIndex = getStoredSubTabIndex(studentId);
    setActiveSubTab(restoredIndex);
    if (SUB_TABS[restoredIndex].key === 'transportFee') {
      setHasFetchedTransport(true);
      fetchTransportInfo();
    }
  }, [studentId]);

  const changeSubTab = (event, newValue) => {
    if (SUB_TABS[newValue].key === 'transportFee' && !hasFetchedTransport) {
      setHasFetchedTransport(true);
      fetchTransportInfo();
    }
    setActiveSubTab(newValue);
    storeSubTabIndex(studentId, newValue);
  };

  // Read-only: routes/stops are created and assigned from the Fees page's Transport Fee tab,
  // this just surfaces what's already assigned to this one student. A student can only have one
  // route/stop per school+batch (StudentTransport is unique on studentId/schoolId/batchId), but
  // the endpoint returns a list, so this still maps over it rather than assuming a single row.
  const fetchTransportInfo = () => {
    if (!studentId) return;
    setIsTransportFetching(true);
    fetchStudentTransportByStudentService(studentId, loggedUserToken)
      .then(rows =>
        Promise.all(
          (rows || []).map(async row => {
            const area = await fetchTransportAreaByIdService(row.transportAreaId, loggedUserToken);
            return { ...row, area, amount: area?.amount ?? null };
          })
        )
      )
      .then(rows => {
        setTransportRows(rows);
        setIsTransportFetching(false);
      })
      .catch(() => setIsTransportFetching(false));
    fetchTransportPayments();
  };

  const fetchTransportPayments = () => {
    if (!studentId) return;
    setIsTransportPaymentsFetching(true);
    fetchTransportPaymentsByStudentService(studentId, loggedUserToken)
      .then(rows => {
        setTransportPayments(rows || []);
        setIsTransportPaymentsFetching(false);
      })
      .catch(() => setIsTransportPaymentsFetching(false));
  };

  // Transport payments are tied to whichever route/stop the student is currently assigned to -
  // there's only ever one (see fetchTransportInfo above), so unlike the fee-structure PaymentForm
  // there's nothing for the admin to pick beyond the month; studentTransportId/transportAreaId/
  // schoolId/batchId all come from that one assignment row.
  const submitTransportPayment = postData => {
    const currentTransport = transportRows?.[0];
    if (!currentTransport) return Promise.reject(new Error('Student has no transport assignment'));
    return createTransportPaymentService(
      {
        ...postData,
        studentTransportId: currentTransport.studentTransportId,
        studentId,
        transportAreaId: currentTransport.transportAreaId,
        schoolId: currentTransport.schoolId,
        batchId: currentTransport.batchId,
      },
      loggedUserToken
    ).then(() => fetchTransportPayments());
  };

  const viewTransportReceipt = async studentTransportPaymentId => {
    setTransportReceiptFetching(studentTransportPaymentId);
    await fetchandShowFeesReceiptReport({
      studentTransportPaymentId,
      apiName: 'generateTransportPaymentReceipt',
      method: 'GET',
      token: loggedUserToken,
      reportName: 'Transport Payment Receipt',
    });
    setTransportReceiptFetching(null);
  };

  const fetchRefundsForPaymentRow = studPaymentId => {
    setIsRefundModalFetching(true);
    Promise.all([
      fetchRefundsForPayment({ studPaymentId, token: loggedUserToken }),
      fetchRefundTotalForPayment({ studPaymentId, token: loggedUserToken }),
    ]).then(() => setIsRefundModalFetching(false));
  };

  const submitRefund = postData => {
    return createRefund({ ...postData, studentId, token: loggedUserToken }).then(() => {
      fetchRefundsForPaymentRow(postData.studPaymentId);
      fetchRefundsForStudentBatch({ studentId, token: loggedUserToken });
    });
  };

  const updatePaySuccess = () => {
    setIsShow(false);
    updateSuccess({ courseId, studentId });
  };

  const viewFeesReceipt = async studPaymentId => {
    const globalSchool = getGlobalSchoolUtils();
    const schoolId = loggedUserSchool || globalSchool?.schoolId || null;
    const { batchId } = getGlobalCurrentBatchUtils();
    if (courseId && studentId) {
      setReceiptFetching(studPaymentId);
      await fetchandShowFeesReceiptReport({
        studPaymentId,
        schoolId,
        apiName: 'generateStudentPaymentReceipt',
        courseId,
        studentId,
        batchId,
        token: loggedUserToken,
        reportName: 'Fees Receipt',
      });
      setReceiptFetching(null);
    }
  };

  const getOnlinePaymentUrl = async () => {
    const globalSchool = getGlobalSchoolUtils() || {};
    const schoolId = loggedUserSchool || globalSchool?.schoolId || null;
    const { batchId } = getGlobalCurrentBatchUtils();
    try {
      const res = await fetchOnlinePaymentLinkApi({ schoolId, batchId, courseId, studentId, token: loggedUserToken });
      if (res.data?.url) {
        window.open(res.data?.url);
      }
    } catch (err) {
      dispatch(showToast(formResMessage(err), 'warning'));
    }
  };

  const schoolFeeSubTab = (
    <>
      {!!feeStructure?.[studentId]?.length && !feeStructureFetching && (
        <FeeSummaryCard
          feeStructure={feeStructure[studentId]}
          payments={payments?.[studentId] || []}
          refunds={refundsByStudent?.[studentId] || []}
        />
      )}
      <Row>
        <Col>
          <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
            <div className="card-category font-weight-bold mb-2" style={{ overflow: 'hidden' }}>
              Fee Structure{' '}
              <div style={{ float: 'right' }}>
                <CustomButton
                  className="mr-2"
                  size="small"
                  variant="outlined"
                  name="Assign Existing Fee Structure"
                  onClick={() => setIsAssignFeeStructureModalOpen(true)}
                />
                <CustomButton
                  size="small"
                  variant="outlined"
                  name="+ Create New Fee Structure"
                  onClick={() => history.push(`/admin/fees?student-fee-structure&returnStudentId=${studentId}`)}
                />
              </div>
            </div>
            <div style={{ overflowX: 'auto' }}>
              <Table size="small" aria-label="a dense table">
                <TableHead>
                  <TableRow style={{ backgroundColor: '#e0e0e0' }}>
                    <TableCell component="th">
                      <b>Fee Name</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Fee Amount</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Discount Amount</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Total Fee</b>
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {feeStructureFetching ? (
                    <TableRow>
                      <TableCell colSpan={6} component="td">
                        <div style={{ textAlign: 'center' }}>
                          <CommonLoader />
                        </div>
                      </TableCell>
                    </TableRow>
                  ) : feeStructure?.[studentId]?.length ? (
                    feeStructure?.[studentId]?.map(item => {
                      return (
                        <TableRow key={item.feeStructId}>
                          <TableCell component="th" scope="row">
                            {item.feeDescription}
                          </TableCell>
                          <TableCell align="left">{`₹${item.actualAmount}`}</TableCell>
                          <TableCell align="left">{`₹${item.discountAmount}` || '--'}</TableCell>
                          <TableCell align="left">
                            <b>{`₹${item.expectedAmount || item.actualAmount - item.discountAmount}` || '--'}</b>
                          </TableCell>
                        </TableRow>
                      );
                    })
                  ) : (
                    <TableRow>
                      <TableCell colSpan={5} component="td">
                        <div style={{ textAlign: 'center', color: '#9a9a9a', padding: '10px 0' }}>
                          No fee structure assigned yet.
                        </div>
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
            <div style={{ fontSize: 12, color: '#9a9a9a', marginTop: 8 }}>
              Also covers one-off charges for this student only - an arrear, a fine, anything beyond the fees every
              student pays.
            </div>
          </Paper>
        </Col>
      </Row>
      <br />
      <Row>
        <Col>
          <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
            <div className="card-category font-weight-bold mb-3" style={{ overflow: 'hidden' }}>
              Payment History{' '}
              <div style={{ float: 'right' }}>
                <CustomButton
                  variant="outlined"
                  size="small"
                  name="Make online payment"
                  onClick={() => getOnlinePaymentUrl()}
                />
                <CustomButton
                  className="ml-2"
                  size="small"
                  name="Add payment"
                  onClick={() => setIsShow(true)}
                  style={{ backgroundColor: colors.accent, color: colors.white }}
                />
              </div>
            </div>
            <PaymentForm
              isShow={isShow}
              courseId={courseId}
              studentId={studentId}
              studentFeesStructures={feeStructure?.[studentId]}
              hideForm={() => setIsShow(false)}
              payStudentFeePayment={payStudentFeePayment}
              updateSuccess={updatePaySuccess}
            />
            {!!payments?.[studentId]?.length &&
              (() => {
                const totalPaid = payments[studentId].reduce((acc, item) => acc + Number(item.amount || 0), 0);
                const totalRefunded = (refundsByStudent?.[studentId] || []).reduce(
                  (acc, el) => acc + Number(el.refundAmount || 0),
                  0
                );
                return (
                  <div style={{ fontSize: 13, marginBottom: 10, color: '#6b778a' }}>
                    Total paid: <b>{formatMoney(totalPaid)}</b>
                    {!!totalRefunded && (
                      <>
                        {' '}
                        &middot; Refunded: <b>{formatMoney(totalRefunded)}</b> &middot; Net paid:{' '}
                        <b>{formatMoney(totalPaid - totalRefunded)}</b>
                      </>
                    )}
                  </div>
                );
              })()}
            <div style={{ overflowX: 'auto' }}>
              <Table size="small" aria-label="a dense table">
                <TableHead>
                  <TableRow style={{ backgroundColor: '#e0e0e0' }}>
                    <TableCell component="th">
                      <b>Fee Name</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Amount Paid</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Transaction Id</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Payment Date</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Pay Mode</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Status</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Comments</b>
                    </TableCell>
                    <TableCell component="th" align="center">
                      <b>View Receipt</b>
                    </TableCell>
                    <TableCell component="th" align="center">
                      <b>Refund</b>
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {paymentsFetching ? (
                    <TableRow>
                      <TableCell colSpan={9} component="td">
                        <div style={{ textAlign: 'center' }}>
                          <CommonLoader />
                        </div>
                      </TableCell>
                    </TableRow>
                  ) : payments?.[studentId]?.length ? (
                    payments?.[studentId]?.map(item => {
                      return (
                        <TableRow key={item.studPaymentId}>
                          <TableCell component="th" scope="row">
                            {item?.feeDescription}
                          </TableCell>
                          <TableCell align="left">{`₹${item.amount}`}</TableCell>
                          <TableCell align="left">{`${item.transactionId}`}</TableCell>
                          <TableCell align="left">{moment(item.paymentDate).format('DD MMM, YYYY hh:mm A')}</TableCell>
                          <TableCell align="left">{`${item.paymentMode}` || '--'}</TableCell>
                          <TableCell align="left">{formatPaidStatus(item.paidStatus)}</TableCell>
                          <TableCell align="left">{item.paymentNotes || '--'}</TableCell>
                          <TableCell align="center">
                            {receiptFetchingId === item.studPaymentId ? (
                              <CircularProgress size={15} />
                            ) : (
                              <span
                                onClick={() => viewFeesReceipt(item.studPaymentId)}
                                style={{ color: 'blue', cursor: 'pointer' }}>
                                <b>View</b>
                              </span>
                            )}
                          </TableCell>
                          <TableCell align="center">
                            <span
                              onClick={() => setRefundPayment(item)}
                              style={{ color: colors.accent, cursor: 'pointer' }}>
                              <b>Refund</b>
                            </span>
                          </TableCell>
                        </TableRow>
                      );
                    })
                  ) : (
                    <TableRow>
                      <TableCell colSpan={9} component="td">
                        <EmptyState compact bare icon="fas fa-receipt" title="Nothing to show here yet" />
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
          </Paper>
        </Col>
      </Row>
    </>
  );

  const transportFeeSubTab = (
    <>
      {!!transportRows?.length && (
        <TransportSummaryCard monthlyFee={transportRows[0].amount || 0} payments={transportPayments || []} />
      )}
      <Row>
        <Col>
          <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
            <div className="card-category font-weight-bold mb-2" style={{ overflow: 'hidden' }}>
              Transport Fee{' '}
              <div style={{ float: 'right' }}>
                <CustomButton
                  className="mr-2"
                  size="small"
                  variant="outlined"
                  name="Assign Existing Route"
                  onClick={() => setIsAssignRouteModalOpen(true)}
                />
                <CustomButton
                  size="small"
                  variant="outlined"
                  name="+ Create New Route"
                  onClick={() => history.push(`/admin/fees?transport-fee&returnStudentId=${studentId}`)}
                />
              </div>
            </div>
            {isTransportFetching ? (
              <div style={{ textAlign: 'center' }}>
                <CommonLoader />
              </div>
            ) : transportRows?.length ? (
              <div style={{ overflowX: 'auto' }}>
                <Table size="small" aria-label="a dense table">
                  <TableHead>
                    <TableRow style={{ backgroundColor: '#e0e0e0' }}>
                      <TableCell component="th">
                        <b>Route Name</b>
                      </TableCell>
                      <TableCell component="th" align="left">
                        <b>Destination</b>
                      </TableCell>
                      <TableCell component="th" align="left">
                        <b>Distance</b>
                      </TableCell>
                      <TableCell component="th" align="left">
                        <b>Fee</b>
                      </TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {transportRows.map(row => (
                      <TableRow key={row.studentTransportId}>
                        <TableCell component="th" scope="row">
                          {row.area?.ruteName}
                        </TableCell>
                        <TableCell align="left">{row.area?.areaName}</TableCell>
                        <TableCell align="left">
                          {row.area?.distance != null ? `${row.area.distance} km` : 'N/A'}
                        </TableCell>
                        <TableCell align="left">
                          <b>{row.amount !== null ? formatMoney(row.amount) : '--'}</b>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            ) : (
              <div style={{ textAlign: 'center', color: '#9a9a9a', padding: '10px 0' }}>
                This student has no transport route assigned.
              </div>
            )}
          </Paper>
        </Col>
      </Row>
      <br />
      <Row>
        <Col>
          <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
            <div className="card-category font-weight-bold mb-3" style={{ overflow: 'hidden' }}>
              Transport Payment History{' '}
              <div style={{ float: 'right' }}>
                <CustomButton
                  size="small"
                  name="Add payment"
                  disabled={!transportRows?.length}
                  onClick={() => setIsTransportPaymentFormOpen(true)}
                  style={{ backgroundColor: colors.accent, color: colors.white }}
                />
              </div>
            </div>
            <TransportPaymentForm
              isShow={isTransportPaymentFormOpen}
              defaultAmount={transportRows?.[0]?.amount || 0}
              existingMonths={(transportPayments || []).flatMap(el =>
                (el.paymentMonth || '').split(',').map(m => m.trim())
              )}
              hideForm={() => setIsTransportPaymentFormOpen(false)}
              onSave={submitTransportPayment}
            />
            {!!transportPayments?.length && (
              <div style={{ fontSize: 13, marginBottom: 10, color: '#6b778a' }}>
                Total paid:{' '}
                <b>{formatMoney(transportPayments.reduce((acc, item) => acc + Number(item.amount || 0), 0))}</b>
              </div>
            )}
            <div style={{ overflowX: 'auto' }}>
              <Table size="small" aria-label="a dense table">
                <TableHead>
                  <TableRow style={{ backgroundColor: '#e0e0e0' }}>
                    <TableCell component="th">
                      <b>Month</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Amount Paid</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Transaction Id</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Payment Date</b>
                    </TableCell>
                    <TableCell component="th" align="left">
                      <b>Comments</b>
                    </TableCell>
                    <TableCell component="th" align="center">
                      <b>Receipt</b>
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {isTransportPaymentsFetching ? (
                    <TableRow>
                      <TableCell colSpan={6} component="td">
                        <div style={{ textAlign: 'center' }}>
                          <CommonLoader />
                        </div>
                      </TableCell>
                    </TableRow>
                  ) : transportPayments?.length ? (
                    transportPayments.map(item => (
                      <TableRow key={item.studentTransportPaymentId}>
                        <TableCell component="th" scope="row">
                          {item.paymentMonth}
                        </TableCell>
                        <TableCell align="left">{formatMoney(item.amount)}</TableCell>
                        <TableCell align="left">{item.transactionId || '--'}</TableCell>
                        <TableCell align="left">{moment(item.paymentDate).format('DD MMM, YYYY hh:mm A')}</TableCell>
                        <TableCell align="left">{item.notes || '--'}</TableCell>
                        <TableCell align="center">
                          {transportReceiptFetchingId === item.studentTransportPaymentId ? (
                            <CircularProgress size={15} />
                          ) : (
                            <span
                              onClick={() => viewTransportReceipt(item.studentTransportPaymentId)}
                              style={{ color: 'blue', cursor: 'pointer' }}>
                              <b>View</b>
                            </span>
                          )}
                        </TableCell>
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell colSpan={6} component="td" style={{ textAlign: 'center', color: '#9a9a9a' }}>
                        No transport payments recorded yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
          </Paper>
        </Col>
      </Row>
    </>
  );

  const billingsSubTab = (
    <StudentBillsPanel studentId={studentId} loggedUserSchool={loggedUserSchool} loggedUserToken={loggedUserToken} />
  );

  const refundsSubTab = (
    <Row>
      <Col>
        <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
          <div className="card-category font-weight-bold mb-3" style={{ overflow: 'hidden' }}>
            Refund History
          </div>
          {!!refundsByStudent?.[studentId]?.length && (
            <div style={{ fontSize: 13, marginBottom: 10, color: '#6b778a' }}>
              Total refunded:{' '}
              <b>
                {formatMoney(refundsByStudent[studentId].reduce((acc, el) => acc + Number(el.refundAmount || 0), 0))}
              </b>
            </div>
          )}
          <div style={{ overflowX: 'auto' }}>
            <Table size="small" aria-label="a dense table">
              <TableHead>
                <TableRow style={{ backgroundColor: '#e0e0e0' }}>
                  <TableCell component="th">
                    <b>Fee Name</b>
                  </TableCell>
                  <TableCell component="th" align="left">
                    <b>Refund Amount</b>
                  </TableCell>
                  <TableCell component="th" align="left">
                    <b>Refund Date</b>
                  </TableCell>
                  <TableCell component="th" align="left">
                    <b>Mode</b>
                  </TableCell>
                  <TableCell component="th" align="left">
                    <b>Status</b>
                  </TableCell>
                  <TableCell component="th" align="left">
                    <b>Reason</b>
                  </TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {refundsByStudent?.[studentId]?.length ? (
                  refundsByStudent[studentId].map(item => {
                    const payment = payments?.[studentId]?.find(p => p.studPaymentId === item.studPaymentId);
                    return (
                      <TableRow key={item.refundId}>
                        <TableCell component="th" scope="row">
                          {payment?.feeDescription || '--'}
                        </TableCell>
                        <TableCell align="left">{formatMoney(item.refundAmount)}</TableCell>
                        <TableCell align="left">
                          {item.refundDate ? moment(item.refundDate).format('DD MMM, YYYY hh:mm A') : '--'}
                        </TableCell>
                        <TableCell align="left">{formatEnumLabel(item.refundMode)}</TableCell>
                        <TableCell align="left">{formatEnumLabel(item.refundStatus)}</TableCell>
                        <TableCell align="left">{item.refundReason || '--'}</TableCell>
                      </TableRow>
                    );
                  })
                ) : (
                  <TableRow>
                    <TableCell colSpan={6} component="td">
                      <div style={{ textAlign: 'center', color: '#9a9a9a', padding: '10px 0' }}>
                        No refunds recorded for this student yet.
                      </div>
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>
          {/* Per-refund PDF receipt isn't available yet - the backend only has
              generateStudentPaymentReceiptPdf/generateTransportPaymentReceiptPdf for payments,
              no equivalent for StudentFeeRefund. Refunds only show up today inside the school-wide
              Finance Report PDF (Reports > Finance, FEE_REFUND transaction type). */}
        </Paper>
      </Col>
    </Row>
  );

  const subTabContent = [schoolFeeSubTab, transportFeeSubTab, refundsSubTab, billingsSubTab];

  return (
    <div>
      <Paper square style={{ marginBottom: 16 }}>
        <Tabs
          value={activeSubTab}
          onChange={changeSubTab}
          TabIndicatorProps={{ style: { display: 'none' } }}
          textColor="inherit"
          variant="standard">
          {SUB_TABS.map((tab, index) => (
            <Tab
              key={tab.key}
              label={tab.label}
              style={{
                fontWeight: 'bold',
                color: activeSubTab === index ? colors.accent : '',
                borderBottom: activeSubTab === index ? `3px solid ${colors.accent}` : '',
              }}
            />
          ))}
        </Tabs>
      </Paper>
      {
        // Keyed by tab so switching subtabs always fully unmounts the old one instead of React
        // trying to reconcile two differently-shaped tables in place - without this, quickly
        // switching subtabs could leave stale rows from the previous subtab's table behind,
        // since its <TableRow> keys (feeStructId, studentTransportId, ...) live in separate id
        // spaces and can coincidentally collide across subtabs.
        <div key={SUB_TABS[activeSubTab].key}>{subTabContent[activeSubTab]}</div>
      }
      <PaymentRefundModal
        isOpen={!!refundPayment}
        onClose={() => setRefundPayment(null)}
        payment={refundPayment}
        refunds={refundsByPayment?.[refundPayment?.studPaymentId] || []}
        totalRefunded={refundTotalByPayment?.[refundPayment?.studPaymentId] || 0}
        isFetching={isRefundModalFetching}
        onFetch={fetchRefundsForPaymentRow}
        onSubmit={submitRefund}
        showWarning={(msg, type) => dispatch(showToast(msg, type))}
      />
      <AssignRouteModal
        isShow={isAssignRouteModalOpen}
        hideForm={() => setIsAssignRouteModalOpen(false)}
        schoolId={schoolId}
        batchId={batchId}
        studentId={studentId}
        loggedUserToken={loggedUserToken}
        onAssigned={() => {
          dispatch(showToast('Route assigned successfully', 'success'));
          fetchTransportInfo();
        }}
      />
      <AssignFeeStructureModal
        isShow={isAssignFeeStructureModalOpen}
        hideForm={() => setIsAssignFeeStructureModalOpen(false)}
        schoolId={schoolId}
        studentId={studentId}
        loggedUserToken={loggedUserToken}
        onAssigned={() => {
          dispatch(showToast('Fee structure assigned successfully', 'success'));
          fetchInfo('feeStructure', { studentId, courseId });
        }}
      />
    </div>
  );
}
