import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label } from 'reactstrap';
import Select from 'react-select';
import CustomButton from 'components/CustomButton';
import { selectStyle } from 'views/admin/Reports';
import { formResMessage } from 'utils/commonFunc';
import colors from 'config/colors';
import {
  fetchAllFeeGroupPlainService,
  fetchAllFeeStructurePlainService,
  saveAssignedStudentForFeeStructureService,
} from 'actions/admin/fees';

// Lets an admin assign an already-existing fee structure line to a student right from the
// student's own Fees tab, instead of having to go find that student inside the Fees page's
// per-structure assign flow.
const AssignFeeStructureModal = ({ isShow, hideForm, schoolId, studentId, loggedUserToken, onAssigned }) => {
  const [feeGroups, setFeeGroups] = useState([]);
  const [feeGroupsLoading, setFeeGroupsLoading] = useState(false);
  const [selectedFeeGroupId, setSelectedFeeGroupId] = useState(null);
  const [structures, setStructures] = useState([]);
  const [structuresLoading, setStructuresLoading] = useState(false);
  const [selectedFeeStructId, setSelectedFeeStructId] = useState(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!isShow) return;
    setSelectedFeeGroupId(null);
    setSelectedFeeStructId(null);
    setStructures([]);
    setError('');
    setFeeGroupsLoading(true);
    fetchAllFeeGroupPlainService(schoolId, loggedUserToken)
      .then(rows => setFeeGroups(rows || []))
      .catch(() => setError('Could not load fee groups'))
      .finally(() => setFeeGroupsLoading(false));
  }, [isShow]);

  const feeGroupOptions = feeGroups.map(g => ({ value: g.feeGroupId, label: g.groupName }));
  const structureOptions = structures.map(s => ({
    value: s.feeStructId,
    label: s.feeDescription,
    amount: s.expectedAmount ?? (s.actualAmount || 0) - (s.discountAmount || 0),
  }));

  const onFeeGroupChange = dto => {
    setSelectedFeeGroupId(dto.value);
    setSelectedFeeStructId(null);
    setStructures([]);
    setStructuresLoading(true);
    fetchAllFeeStructurePlainService(schoolId, dto.value, loggedUserToken)
      .then(rows => setStructures(rows || []))
      .catch(() => setError('Could not load fee structures'))
      .finally(() => setStructuresLoading(false));
  };

  const close = () => {
    setSaving(false);
    hideForm();
  };

  const handleAssign = async () => {
    if (!selectedFeeStructId) {
      setError('Pick a fee structure');
      return;
    }
    setSaving(true);
    try {
      await saveAssignedStudentForFeeStructureService({
        schoolId,
        token: loggedUserToken,
        postData: [{ studentId, feeStructId: selectedFeeStructId }],
      })();
      setSaving(false);
      close();
      onAssigned();
    } catch (err) {
      setSaving(false);
      setError(formResMessage(err));
    }
  };

  return (
    <Modal size="md" scrollable centered isOpen={isShow} className="modal-offset-sidebar">
      <ModalHeader toggle={close}>Assign Existing Fee Structure</ModalHeader>
      <ModalBody>
        {!!error && <div className="err-msg mb-2">{error}</div>}
        <Row>
          <Col md={12}>
            <div className="mb-3">
              <Label>
                Fee Group<sup> *</sup>
              </Label>
              <Select
                name="feeGroup"
                isLoading={feeGroupsLoading}
                options={feeGroupOptions}
                value={feeGroupOptions.find(el => el.value === selectedFeeGroupId) || null}
                onChange={onFeeGroupChange}
                styles={selectStyle(true)}
              />
            </div>
          </Col>
          <Col md={12}>
            <div className="mb-3">
              <Label>
                Fee / Term<sup> *</sup>
              </Label>
              <Select
                name="feeStructure"
                isLoading={structuresLoading}
                isDisabled={!selectedFeeGroupId}
                options={structureOptions}
                value={structureOptions.find(el => el.value === selectedFeeStructId) || null}
                onChange={dto => setSelectedFeeStructId(dto.value)}
                formatOptionLabel={dto => (
                  <span>
                    {dto.label} {dto.amount !== undefined && <span style={{ color: '#6b778a' }}>(₹{dto.amount})</span>}
                  </span>
                )}
                styles={selectStyle(true)}
              />
            </div>
          </Col>
        </Row>
      </ModalBody>
      <ModalFooter>
        <CustomButton className="mr-2" type="button" color="default" disabled={saving} onClick={close} name="Cancel" />
        <CustomButton
          type="button"
          name="Assign"
          disabled={saving}
          loading={saving}
          onClick={handleAssign}
          style={{ backgroundColor: colors.accent, color: colors.white }}
        />
      </ModalFooter>
    </Modal>
  );
};

export default AssignFeeStructureModal;
